LOGIN_HTML = '<!DOCTYPE html>\n<html lang="pt-BR" class="dark">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>Entrar | FinFlow - Gestão Financeira Pessoal</title>\n  \n  <!-- Tailwind CSS CDN -->\n  <script src="https://cdn.tailwindcss.com"></script>\n  <script>\n    tailwind.config = {\n      darkMode: \'class\',\n      theme: {\n        extend: {\n          colors: {\n            brand: {\n              50: \'#eef2ff\',\n              100: \'#e0e7ff\',\n              500: \'#6366f1\',\n              600: \'#4f46e5\',\n              700: \'#4338ca\',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <!-- Google Fonts: Inter -->\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">\n\n  <!-- Lucide Icons -->\n  <script src="https://unpkg.com/lucide@latest"></script>\n\n  <!-- SweetAlert2 -->\n  <script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>\n\n  <!-- Google Identity Services (GSI) -->\n  <script src="https://accounts.google.com/gsi/client" async defer></script>\n\n  <!-- Custom CSS -->\n  <link rel="stylesheet" href="/static/css/styles.css">\n</head>\n<body class="bg-slate-50 dark:bg-slate-950 text-slate-800 dark:text-slate-100 min-h-screen flex flex-col justify-between font-sans selection:bg-indigo-500 selection:text-white transition-colors duration-200 relative overflow-x-hidden">\n\n  <!-- Glow de fundo sutil -->\n  <div class="absolute -top-40 left-1/2 -translate-x-1/2 w-[600px] h-[350px] bg-indigo-500/10 dark:bg-indigo-600/15 blur-[120px] pointer-events-none rounded-full"></div>\n\n  <!-- Header Superior -->\n  <header class="max-w-7xl w-full mx-auto px-6 py-5 flex items-center justify-between relative z-10">\n    <div class="flex items-center gap-3">\n      <div class="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-600 to-violet-500 flex items-center justify-center text-white shadow-lg shadow-indigo-500/20">\n        <i data-lucide="wallet-cards" class="w-5 h-5"></i>\n      </div>\n      <div>\n        <h1 class="text-lg font-bold tracking-tight text-slate-900 dark:text-white flex items-center gap-2">\n          FinFlow <span class="text-[10px] px-2 py-0.5 rounded-full bg-indigo-100 dark:bg-indigo-900/60 text-indigo-700 dark:text-indigo-300 font-semibold border border-indigo-200 dark:border-indigo-700/40">PRO</span>\n        </h1>\n        <p class="text-xs text-slate-500 dark:text-slate-400">Controle Financeiro Pessoal</p>\n      </div>\n    </div>\n\n    <!-- Alternar Tema (Modo Claro / Modo Escuro) -->\n    <button id="btn-theme-login" title="Alternar tema claro/escuro" class="p-2.5 rounded-xl text-slate-500 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white bg-white/80 dark:bg-slate-900/80 hover:bg-slate-100 dark:hover:bg-slate-800 border border-slate-200 dark:border-slate-800 shadow-sm transition">\n      <i id="theme-login-icon" data-lucide="sun" class="w-5 h-5"></i>\n    </button>\n  </header>\n\n  <!-- Card Central de Login / Cadastro -->\n  <main class="flex-1 flex items-center justify-center px-4 py-8 relative z-10">\n    <div class="w-full max-w-md bg-white/90 dark:bg-slate-900/90 border border-slate-200 dark:border-slate-800 rounded-3xl p-6 sm:p-8 shadow-xl dark:shadow-2xl dark:shadow-indigo-950/40 backdrop-blur-xl relative overflow-hidden transition-colors duration-200">\n      \n      <!-- Detalhe decorativo no topo -->\n      <div class="absolute top-0 left-0 right-0 h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500"></div>\n\n      <!-- Abas de Alternância: Entrar vs Cadastrar -->\n      <div class="grid grid-cols-2 gap-1 bg-slate-100 dark:bg-slate-950/80 p-1.5 rounded-2xl border border-slate-200 dark:border-slate-800/80 mb-6">\n        <button id="tab-btn-login" class="py-2.5 rounded-xl text-xs sm:text-sm font-bold transition flex items-center justify-center gap-2 bg-indigo-600 text-white shadow-md shadow-indigo-600/30">\n          <i data-lucide="log-in" class="w-4 h-4"></i>\n          <span>Entrar</span>\n        </button>\n        <button id="tab-btn-register" class="py-2.5 rounded-xl text-xs sm:text-sm font-bold transition flex items-center justify-center gap-2 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200">\n          <i data-lucide="user-plus" class="w-4 h-4"></i>\n          <span>Criar Conta</span>\n        </button>\n      </div>\n\n      <!-- BOTÃO GOOGLE SIGN-IN EM DESTAQUE -->\n      <div class="space-y-4">\n        \n        <!-- Botão customizado ou gatilho Google -->\n        <button id="btn-google-login" type="button" class="w-full flex items-center justify-center gap-3 py-3 px-4 rounded-2xl bg-white hover:bg-slate-50 dark:bg-slate-800 dark:hover:bg-slate-750 text-slate-700 dark:text-slate-200 text-sm font-semibold transition shadow-sm hover:shadow border border-slate-200 dark:border-slate-700 transform hover:-translate-y-0.5 active:translate-y-0">\n          <!-- Ícone oficial do Google SVG -->\n          <svg class="w-5 h-5 shrink-0" viewBox="0 0 24 24">\n            <path fill="#4285F4" d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z"/>\n            <path fill="#34A853" d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z"/>\n            <path fill="#FBBC05" d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.06H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.94l2.85-2.22.81-.63z"/>\n            <path fill="#EA4335" d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.06l3.66 2.84c.87-2.6 3.3-4.52 6.16-4.52z"/>\n          </svg>\n          <span class="whitespace-nowrap">Continuar com Google / Gmail</span>\n        </button>\n\n        <!-- Divisor corrigido sem quebra de linha -->\n        <div class="relative flex items-center justify-center my-5">\n          <div class="border-t border-slate-200 dark:border-slate-800 flex-1"></div>\n          <span class="px-3 text-[11px] font-semibold text-slate-400 dark:text-slate-500 uppercase tracking-wider shrink-0 whitespace-nowrap select-none">\n            ou com seu e-mail\n          </span>\n          <div class="border-t border-slate-200 dark:border-slate-800 flex-1"></div>\n        </div>\n      </div>\n\n      <!-- FORMULÁRIO 1: LOGIN -->\n      <form id="form-login" class="mt-2 space-y-4">\n        <div>\n          <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1.5">E-mail</label>\n          <div class="relative">\n            <i data-lucide="mail" class="w-4 h-4 absolute left-3.5 top-3 text-slate-400"></i>\n            <input type="email" id="login-email" required placeholder="seuemail@exemplo.com" class="w-full pl-10 pr-3 py-2.5 text-sm bg-slate-50 dark:bg-slate-950/70 border border-slate-200 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 focus:outline-none focus:bg-white dark:focus:bg-slate-950 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 transition">\n          </div>\n        </div>\n\n        <div>\n          <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1.5">Senha</label>\n          <div class="relative">\n            <i data-lucide="lock" class="w-4 h-4 absolute left-3.5 top-3 text-slate-400"></i>\n            <input type="password" id="login-senha" required placeholder="••••••••" class="w-full pl-10 pr-10 py-2.5 text-sm bg-slate-50 dark:bg-slate-950/70 border border-slate-200 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 focus:outline-none focus:bg-white dark:focus:bg-slate-950 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 transition">\n            <button type="button" class="btn-toggle-password absolute right-3 top-3 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition">\n              <i data-lucide="eye" class="w-4 h-4"></i>\n            </button>\n          </div>\n        </div>\n\n        <button type="submit" class="w-full py-3 px-4 rounded-xl text-sm font-semibold text-white bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 shadow-lg shadow-indigo-600/30 transition transform hover:-translate-y-0.5 flex items-center justify-center gap-2">\n          <span>Entrar no FinFlow</span>\n          <i data-lucide="arrow-right" class="w-4 h-4"></i>\n        </button>\n      </form>\n\n      <!-- FORMULÁRIO 2: CADASTRO -->\n      <form id="form-register" class="mt-2 space-y-4 hidden">\n        <div>\n          <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1.5">Nome Completo</label>\n          <div class="relative">\n            <i data-lucide="user" class="w-4 h-4 absolute left-3.5 top-3 text-slate-400"></i>\n            <input type="text" id="reg-nome" required placeholder="Como deseja ser chamado(a)" class="w-full pl-10 pr-3 py-2.5 text-sm bg-slate-50 dark:bg-slate-950/70 border border-slate-200 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 focus:outline-none focus:bg-white dark:focus:bg-slate-950 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 transition">\n          </div>\n        </div>\n\n        <div>\n          <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1.5">E-mail</label>\n          <div class="relative">\n            <i data-lucide="mail" class="w-4 h-4 absolute left-3.5 top-3 text-slate-400"></i>\n            <input type="email" id="reg-email" required placeholder="seuemail@exemplo.com" class="w-full pl-10 pr-3 py-2.5 text-sm bg-slate-50 dark:bg-slate-950/70 border border-slate-200 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 focus:outline-none focus:bg-white dark:focus:bg-slate-950 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 transition">\n          </div>\n        </div>\n\n        <div>\n          <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1.5">Senha (mínimo 6 caracteres)</label>\n          <div class="relative">\n            <i data-lucide="lock" class="w-4 h-4 absolute left-3.5 top-3 text-slate-400"></i>\n            <input type="password" id="reg-senha" required minlength="6" placeholder="Crie uma senha forte" class="w-full pl-10 pr-10 py-2.5 text-sm bg-slate-50 dark:bg-slate-950/70 border border-slate-200 dark:border-slate-800 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:border-indigo-500 focus:outline-none focus:bg-white dark:focus:bg-slate-950 text-slate-900 dark:text-white placeholder-slate-400 dark:placeholder-slate-500 transition">\n            <button type="button" class="btn-toggle-password absolute right-3 top-3 text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 transition">\n              <i data-lucide="eye" class="w-4 h-4"></i>\n            </button>\n          </div>\n        </div>\n\n        <button type="submit" class="w-full py-3 px-4 rounded-xl text-sm font-semibold text-white bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 shadow-lg shadow-indigo-600/30 transition transform hover:-translate-y-0.5 flex items-center justify-center gap-2">\n          <span>Criar Minha Conta Grátis</span>\n          <i data-lucide="check" class="w-4 h-4"></i>\n        </button>\n      </form>\n\n      <div class="mt-6 text-center text-[11px] text-slate-500 dark:text-slate-400">\n        Seus dados financeiros são salvos localmente e protegidos de ponta a ponta.\n      </div>\n\n    </div>\n  </main>\n\n  <!-- Rodapé -->\n  <footer class="py-4 text-center text-xs text-slate-500 dark:text-slate-400 relative z-10">\n    FinFlow &bull; Sistema de Gestão Financeira Pessoal Inteligente\n  </footer>\n\n  <!-- Script de Login / Cadastro -->\n  <script>\n    // Configuração do Google Client ID (injetada pelo Flask ou via API)\n    const GOOGLE_CLIENT_ID = "{{ google_client_id | default(\'\') }}";\n\n    document.addEventListener(\'DOMContentLoaded\', () => {\n      initLoginTheme();\n      setupAuthTabs();\n      setupPasswordToggles();\n      setupForms();\n      setupGoogleAuth();\n      lucide.createIcons();\n    });\n\n    // Controle de Tema no Login\n    function initLoginTheme() {\n      const savedTheme = localStorage.getItem(\'finflow_theme\') || \'dark\';\n      if (savedTheme === \'dark\') {\n        document.documentElement.classList.add(\'dark\');\n      } else {\n        document.documentElement.classList.remove(\'dark\');\n      }\n      updateLoginThemeIcon();\n\n      document.getElementById(\'btn-theme-login\')?.addEventListener(\'click\', () => {\n        const isDark = document.documentElement.classList.toggle(\'dark\');\n        localStorage.setItem(\'finflow_theme\', isDark ? \'dark\' : \'light\');\n        updateLoginThemeIcon();\n      });\n    }\n\n    function updateLoginThemeIcon() {\n      const isDark = document.documentElement.classList.contains(\'dark\');\n      const btn = document.getElementById(\'btn-theme-login\');\n      if (btn) {\n        btn.innerHTML = `<i data-lucide="${isDark ? \'sun\' : \'moon\'}" class="w-5 h-5"></i>`;\n        btn.setAttribute(\'title\', isDark ? \'Mudar para tema claro\' : \'Mudar para tema escuro\');\n        lucide.createIcons();\n      }\n    }\n\n    // Alternância de Abas: Entrar vs Criar Conta\n    function setupAuthTabs() {\n      const btnLogin = document.getElementById(\'tab-btn-login\');\n      const btnRegister = document.getElementById(\'tab-btn-register\');\n      const formLogin = document.getElementById(\'form-login\');\n      const formRegister = document.getElementById(\'form-register\');\n\n      if (!btnLogin || !btnRegister) return;\n\n      btnLogin.addEventListener(\'click\', () => {\n        btnLogin.className = \'py-2.5 rounded-xl text-xs sm:text-sm font-bold transition flex items-center justify-center gap-2 bg-indigo-600 text-white shadow-md shadow-indigo-600/30\';\n        btnRegister.className = \'py-2.5 rounded-xl text-xs sm:text-sm font-bold transition flex items-center justify-center gap-2 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200\';\n        formLogin.classList.remove(\'hidden\');\n        formRegister.classList.add(\'hidden\');\n      });\n\n      btnRegister.addEventListener(\'click\', () => {\n        btnRegister.className = \'py-2.5 rounded-xl text-xs sm:text-sm font-bold transition flex items-center justify-center gap-2 bg-indigo-600 text-white shadow-md shadow-indigo-600/30\';\n        btnLogin.className = \'py-2.5 rounded-xl text-xs sm:text-sm font-bold transition flex items-center justify-center gap-2 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-slate-200\';\n        formRegister.classList.remove(\'hidden\');\n        formLogin.classList.add(\'hidden\');\n      });\n    }\n\n    // Alternar visibilidade de senha\n    function setupPasswordToggles() {\n      document.querySelectorAll(\'.btn-toggle-password\').forEach(btn => {\n        btn.addEventListener(\'click\', () => {\n          const input = btn.previousElementSibling;\n          if (input.type === \'password\') {\n            input.type = \'text\';\n            btn.innerHTML = \'<i data-lucide="eye-off" class="w-4 h-4"></i>\';\n          } else {\n            input.type = \'password\';\n            btn.innerHTML = \'<i data-lucide="eye" class="w-4 h-4"></i>\';\n          }\n          lucide.createIcons();\n        });\n      });\n    }\n\n    // Submissão de formulários\n    function setupForms() {\n      // Submeter Login\n      document.getElementById(\'form-login\')?.addEventListener(\'submit\', async (e) => {\n        e.preventDefault();\n        const email = document.getElementById(\'login-email\').value.trim();\n        const senha = document.getElementById(\'login-senha\').value;\n\n        try {\n          const res = await fetch(\'/api/auth/login\', {\n            method: \'POST\',\n            headers: { \'Content-Type\': \'application/json\' },\n            body: JSON.stringify({ email, senha })\n          });\n          const data = await res.json();\n\n          if (res.ok && data.success) {\n            Swal.fire({\n              icon: \'success\',\n              title: data.message || \'Login realizado!\',\n              timer: 1000,\n              showConfirmButton: false\n            }).then(() => {\n              window.location.href = \'/\';\n            });\n          } else {\n            Swal.fire({\n              icon: \'error\',\n              title: \'Não foi possível entrar\',\n              text: data.error || \'Verifique seus dados e tente novamente.\'\n            });\n          }\n        } catch (err) {\n          Swal.fire({ icon: \'error\', title: \'Erro de Conexão\', text: \'Não foi possível conectar ao servidor.\' });\n        }\n      });\n\n      // Submeter Cadastro\n      document.getElementById(\'form-register\')?.addEventListener(\'submit\', async (e) => {\n        e.preventDefault();\n        const nome = document.getElementById(\'reg-nome\').value.trim();\n        const email = document.getElementById(\'reg-email\').value.trim();\n        const senha = document.getElementById(\'reg-senha\').value;\n\n        try {\n          const res = await fetch(\'/api/auth/register\', {\n            method: \'POST\',\n            headers: { \'Content-Type\': \'application/json\' },\n            body: JSON.stringify({ nome, email, senha })\n          });\n          const data = await res.json();\n\n          if (res.ok && data.success) {\n            Swal.fire({\n              icon: \'success\',\n              title: \'Conta Criada!\',\n              text: \'Sua base de dados foi iniciada com sucesso. Redirecionando...\',\n              timer: 1200,\n              showConfirmButton: false\n            }).then(() => {\n              window.location.href = \'/\';\n            });\n          } else {\n            Swal.fire({\n              icon: \'error\',\n              title: \'Erro no Cadastro\',\n              text: data.error || \'Ocorreu um erro ao criar sua conta.\'\n            });\n          }\n        } catch (err) {\n          Swal.fire({ icon: \'error\', title: \'Erro de Conexão\', text: \'Não foi possível conectar ao servidor.\' });\n        }\n      });\n    }\n\n    // Google Sign-In (Nativo GSI com Client ID + Fallback Amigável para Localhost)\n    function setupGoogleAuth() {\n      const isDark = () => document.documentElement.classList.contains(\'dark\');\n\n      // Se GOOGLE_CLIENT_ID estiver presente, inicializa o Google Identity Services oficial\n      if (GOOGLE_CLIENT_ID && typeof google !== \'undefined\' && google.accounts) {\n        google.accounts.id.initialize({\n          client_id: GOOGLE_CLIENT_ID,\n          callback: handleGoogleCredentialResponse\n        });\n      }\n\n      document.getElementById(\'btn-google-login\')?.addEventListener(\'click\', async () => {\n        // Se há Client ID do Google configurado, aciona o prompt nativo oficial da Google\n        if (GOOGLE_CLIENT_ID && typeof google !== \'undefined\' && google.accounts) {\n          google.accounts.id.prompt();\n          return;\n        }\n\n        // Em modo de desenvolvimento local (sem GOOGLE_CLIENT_ID), exibir modal moderno de teste\n        const darkTheme = isDark();\n        const bgModal = darkTheme ? \'#0f172a\' : \'#ffffff\';\n        const textColor = darkTheme ? \'#f8fafc\' : \'#0f172a\';\n        const inputBg = darkTheme ? \'#1e293b\' : \'#f8fafc\';\n        const inputBorder = darkTheme ? \'#334155\' : \'#cbd5e1\';\n\n        const { value: formValues } = await Swal.fire({\n          title: \'<span style="font-size:1.15rem; font-weight:700;">Entrar com Google / Gmail</span>\',\n          background: bgModal,\n          color: textColor,\n          html: `\n            <div class="text-left space-y-3.5 p-1" style="font-size: 0.85rem;">\n              <div class="p-3 rounded-xl ${darkTheme ? \'bg-indigo-950/40 border border-indigo-800/50 text-indigo-300\' : \'bg-indigo-50 border border-indigo-200 text-indigo-800\'} text-xs">\n                <p class="font-bold flex items-center gap-1.5 mb-1">\n                  <span>💡 Modo Desenvolvimento Local:</span>\n                </p>\n                <p>Em produção com a chave <code>GOOGLE_CLIENT_ID</code> configurada, a janela oficial do Google abrirá diretamente para login com 1 clique.</p>\n              </div>\n\n              <div>\n                <label class="block text-xs font-semibold mb-1" style="color: ${darkTheme ? \'#94a3b8\' : \'#475569\'};">Seu Nome</label>\n                <input id="swal-google-nome" style="background:${inputBg}; color:${textColor}; border:1px solid ${inputBorder}; border-radius:0.75rem; width:100%; padding:0.6rem 0.75rem; font-size:0.875rem; outline:none;" placeholder="Ex: Anderson Nogueira" value="Anderson Nogueira">\n              </div>\n\n              <div>\n                <label class="block text-xs font-semibold mb-1" style="color: ${darkTheme ? \'#94a3b8\' : \'#475569\'};">Seu Gmail</label>\n                <input id="swal-google-email" style="background:${inputBg}; color:${textColor}; border:1px solid ${inputBorder}; border-radius:0.75rem; width:100%; padding:0.6rem 0.75rem; font-size:0.875rem; outline:none;" placeholder="seuemail@gmail.com" value="anderson@gmail.com">\n              </div>\n            </div>\n          `,\n          focusConfirm: false,\n          showCancelButton: true,\n          confirmButtonText: \'Continuar com Google\',\n          cancelButtonText: \'Cancelar\',\n          confirmButtonColor: \'#4f46e5\',\n          cancelButtonColor: darkTheme ? \'#475569\' : \'#94a3b8\',\n          customClass: {\n            popup: \'rounded-3xl shadow-2xl\',\n            confirmButton: \'rounded-xl font-bold text-sm px-5 py-2.5 shadow-lg shadow-indigo-600/30\',\n            cancelButton: \'rounded-xl font-semibold text-sm px-4 py-2.5\'\n          },\n          preConfirm: () => {\n            const nome = document.getElementById(\'swal-google-nome\').value.trim();\n            const email = document.getElementById(\'swal-google-email\').value.trim();\n            if (!email || !email.includes(\'@\')) {\n              Swal.showValidationMessage(\'Por favor, informe um e-mail válido\');\n              return false;\n            }\n            return { nome, email };\n          }\n        });\n\n        if (formValues) {\n          try {\n            const res = await fetch(\'/api/auth/google\', {\n              method: \'POST\',\n              headers: { \'Content-Type\': \'application/json\' },\n              body: JSON.stringify({\n                nome: formValues.nome,\n                email: formValues.email,\n                avatar_url: `https://ui-avatars.com/api/?name=${encodeURIComponent(formValues.nome)}&background=6366f1&color=fff`\n              })\n            });\n            const data = await res.json();\n\n            if (res.ok && data.success) {\n              Swal.fire({\n                icon: \'success\',\n                title: \'Conectado com Google!\',\n                timer: 1000,\n                showConfirmButton: false\n              }).then(() => {\n                window.location.href = \'/\';\n              });\n            } else {\n              Swal.fire({ icon: \'error\', title: \'Erro ao entrar com Google\', text: data.error });\n            }\n          } catch (err) {\n            Swal.fire({ icon: \'error\', title: \'Erro\', text: \'Falha na comunicação com o servidor.\' });\n          }\n        }\n      });\n    }\n\n    // Callback para resposta do Google Identity Services oficial (JWT Token)\n    async function handleGoogleCredentialResponse(response) {\n      try {\n        const res = await fetch(\'/api/auth/google\', {\n          method: \'POST\',\n          headers: { \'Content-Type\': \'application/json\' },\n          body: JSON.stringify({ credential: response.credential })\n        });\n        const data = await res.json();\n        if (res.ok && data.success) {\n          Swal.fire({\n            icon: \'success\',\n            title: \'Conectado com Google!\',\n            timer: 1000,\n            showConfirmButton: false\n          }).then(() => {\n            window.location.href = \'/\';\n          });\n        } else {\n          Swal.fire({ icon: \'error\', title: \'Erro na autenticação\', text: data.error });\n        }\n      } catch (err) {\n        Swal.fire({ icon: \'error\', title: \'Erro\', text: \'Falha ao processar login com Google.\' });\n      }\n    }\n  </script>\n</body>\n</html>\n'

INDEX_HTML = '<!DOCTYPE html>\n<html lang="pt-BR" class="dark">\n<head>\n  <meta charset="UTF-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1.0">\n  <title>FinFlow | Gestão Financeira Inteligente</title>\n  \n  <!-- Tailwind CSS CDN -->\n  <script src="https://cdn.tailwindcss.com"></script>\n  <script>\n    tailwind.config = {\n      darkMode: \'class\',\n      theme: {\n        extend: {\n          colors: {\n            brand: {\n              50: \'#eef2ff\',\n              100: \'#e0e7ff\',\n              500: \'#6366f1\',\n              600: \'#4f46e5\',\n              700: \'#4338ca\',\n            }\n          }\n        }\n      }\n    }\n  </script>\n\n  <!-- Google Fonts: Inter -->\n  <link rel="preconnect" href="https://fonts.googleapis.com">\n  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>\n  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">\n\n  <!-- Lucide Icons -->\n  <script src="https://unpkg.com/lucide@latest"></script>\n\n  <!-- Chart.js -->\n  <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>\n\n  <!-- SweetAlert2 -->\n  <script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>\n\n  <!-- Custom CSS -->\n  <link rel="stylesheet" href="/static/css/styles.css">\n</head>\n<body class="bg-slate-50 dark:bg-slate-950 text-slate-800 dark:text-slate-100 min-h-screen flex flex-col font-sans transition-colors duration-200">\n\n  <!-- TOP NAVBAR -->\n  <header class="sticky top-0 z-40 bg-white/80 dark:bg-slate-900/80 backdrop-blur-md border-b border-slate-200/80 dark:border-slate-800 transition-colors">\n    <div class="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">\n      <div class="flex items-center justify-between h-16">\n        \n        <!-- Logo e Título -->\n        <div class="flex items-center gap-3">\n          <div class="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-600 to-violet-500 flex items-center justify-center text-white shadow-lg shadow-indigo-500/20 shrink-0">\n            <i data-lucide="wallet-cards" class="w-5 h-5"></i>\n          </div>\n          <div>\n            <h1 class="text-base sm:text-lg font-bold tracking-tight text-slate-900 dark:text-white flex items-center gap-2">\n              FinFlow <span class="text-[10px] px-2 py-0.5 rounded-full bg-indigo-50 dark:bg-indigo-900/60 text-indigo-700 dark:text-indigo-300 font-semibold border border-indigo-200/60 dark:border-indigo-700/40">PRO</span>\n            </h1>\n            <p class="text-xs text-slate-500 dark:text-slate-400">Controle Financeiro Pessoal</p>\n          </div>\n        </div>\n\n        <!-- Seletor de Mês / Ano Compacto e Elegante -->\n        <div class="flex items-center bg-slate-100/90 dark:bg-slate-800/80 p-1 rounded-xl border border-slate-200/80 dark:border-slate-700/60 shadow-inner">\n          <button id="btn-mes-anterior" title="Mês Anterior" class="p-1.5 rounded-lg hover:bg-white dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 transition">\n            <i data-lucide="chevron-left" class="w-4 h-4"></i>\n          </button>\n          \n          <div class="px-3 py-0.5 flex items-center gap-1.5 min-w-[125px] justify-center">\n            <i data-lucide="calendar" class="w-3.5 h-3.5 text-indigo-500 shrink-0"></i>\n            <span id="label-mes-ano" class="text-xs sm:text-sm font-bold text-slate-800 dark:text-slate-200 select-none whitespace-nowrap">Mês Atual</span>\n          </div>\n\n          <button id="btn-mes-proximo" title="Próximo Mês" class="p-1.5 rounded-lg hover:bg-white dark:hover:bg-slate-700 text-slate-600 dark:text-slate-300 transition">\n            <i data-lucide="chevron-right" class="w-4 h-4"></i>\n          </button>\n\n          <button id="btn-mes-atual" title="Ir para o mês atual" class="ml-1 text-[11px] px-2 py-1 rounded-lg bg-white dark:bg-slate-700 text-indigo-600 dark:text-indigo-300 font-semibold hover:bg-indigo-50 dark:hover:bg-slate-600 transition shadow-sm border border-slate-200/40 dark:border-slate-600/40">\n            Hoje\n          </button>\n        </div>\n\n        <!-- Ações do Topo e Perfil do Usuário -->\n        <div class="flex items-center gap-2 sm:gap-3">\n          <!-- Alternar Tema -->\n          <button id="btn-toggle-theme" title="Alternar Modo Escuro/Claro" class="p-2.5 rounded-xl text-slate-500 hover:text-slate-900 dark:text-slate-400 dark:hover:text-white bg-slate-100/80 dark:bg-slate-800/80 hover:bg-slate-200 dark:hover:bg-slate-700 border border-slate-200/60 dark:border-slate-700/60 transition">\n            <i id="theme-icon" data-lucide="sun" class="w-4 h-4"></i>\n          </button>\n\n          <!-- Botão Importar Extrato Bancário Inteligente -->\n          <button id="btn-open-modal-import" title="Importar arquivo bancário (OFX, CSV, TXT)" class="flex items-center gap-1.5 px-3 py-2 text-xs font-bold text-indigo-700 dark:text-indigo-300 bg-indigo-50 hover:bg-indigo-100 dark:bg-indigo-950/60 dark:hover:bg-indigo-900/60 border border-indigo-200/80 dark:border-indigo-800/80 rounded-xl shadow-sm transition transform hover:-translate-y-0.5">\n            <i data-lucide="file-up" class="w-4 h-4 text-indigo-500"></i>\n            <span class="hidden sm:inline">Importar Extrato</span>\n            <span class="inline-flex items-center px-1.5 py-0.2 rounded-full text-[10px] font-bold bg-indigo-600 text-white">IA</span>\n          </button>\n\n          <!-- Exportar CSV -->\n          <a id="btn-export-csv" href="/api/export/csv" title="Exportar Extrato em CSV / Excel" class="hidden md:flex items-center gap-1.5 px-3 py-2 text-xs font-semibold text-slate-700 dark:text-slate-300 bg-slate-100/80 hover:bg-slate-200 dark:bg-slate-800/80 dark:hover:bg-slate-700 rounded-xl transition border border-slate-200/60 dark:border-slate-700/60">\n            <i data-lucide="download" class="w-3.5 h-3.5"></i>\n            <span>Exportar</span>\n          </a>\n\n          <!-- Botão Novo Lançamento -->\n          <button id="btn-open-modal-lancamento" class="flex items-center gap-2 px-3 sm:px-4 py-2 text-xs sm:text-sm font-bold text-white bg-indigo-600 hover:bg-indigo-700 active:bg-indigo-800 rounded-xl shadow-md shadow-indigo-600/30 transition transform hover:-translate-y-0.5">\n            <i data-lucide="plus-circle" class="w-4 h-4"></i>\n            <span>Novo Lançamento</span>\n            <span class="hidden md:inline text-[10px] bg-indigo-700/80 px-1.5 py-0.5 rounded border border-indigo-400/30">N</span>\n          </button>\n\n          <!-- Perfil do Usuário & Logout -->\n          <div class="flex items-center pl-2 border-l border-slate-200 dark:border-slate-800 gap-2">\n            <div class="flex items-center gap-2">\n              <img id="user-avatar-img" src="https://ui-avatars.com/api/?name=User&background=6366f1&color=fff" class="w-8 h-8 rounded-full border border-slate-300 dark:border-slate-700 object-cover shadow-sm" alt="Avatar">\n              <div class="hidden lg:block text-left">\n                <p id="user-nome-label" class="text-xs font-bold text-slate-800 dark:text-slate-200 leading-tight">Usuário</p>\n                <p id="user-email-label" class="text-[10px] text-slate-400 leading-tight truncate max-w-[110px]">user@exemplo.com</p>\n              </div>\n            </div>\n            \n            <button id="btn-logout" title="Sair da Conta (Logout)" class="p-2 text-slate-400 hover:text-rose-500 hover:bg-rose-50 dark:hover:bg-rose-950/40 rounded-xl transition">\n              <i data-lucide="log-out" class="w-4 h-4"></i>\n            </button>\n          </div>\n        </div>\n\n      </div>\n\n      <!-- TABS DE NAVEGAÇÃO -->\n      <nav class="flex space-x-1 sm:space-x-4 border-t border-slate-200 dark:border-slate-800/80 pt-1 -mb-px overflow-x-auto">\n        <button class="nav-tab active-tab flex items-center gap-2 px-3 sm:px-4 py-2.5 text-xs sm:text-sm font-semibold border-b-2 border-indigo-600 text-indigo-600 dark:text-indigo-400 whitespace-nowrap" data-tab="dashboard">\n          <i data-lucide="layout-dashboard" class="w-4 h-4"></i>\n          <span>Visão Geral</span>\n        </button>\n\n        <button class="nav-tab flex items-center gap-2 px-3 sm:px-4 py-2.5 text-xs sm:text-sm font-medium border-b-2 border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 whitespace-nowrap" data-tab="transacoes">\n          <i data-lucide="arrow-left-right" class="w-4 h-4"></i>\n          <span>Lançamentos & Extrato</span>\n        </button>\n\n        <button class="nav-tab flex items-center gap-2 px-3 sm:px-4 py-2.5 text-xs sm:text-sm font-medium border-b-2 border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 whitespace-nowrap" data-tab="recorrencias">\n          <i data-lucide="refresh-cw" class="w-4 h-4"></i>\n          <span>Despesas Fixas / Recorrentes</span>\n        </button>\n\n        <button class="nav-tab flex items-center gap-2 px-3 sm:px-4 py-2.5 text-xs sm:text-sm font-medium border-b-2 border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 whitespace-nowrap" data-tab="contas">\n          <i data-lucide="landmark" class="w-4 h-4"></i>\n          <span>Contas Bancárias</span>\n        </button>\n\n        <button class="nav-tab flex items-center gap-2 px-3 sm:px-4 py-2.5 text-xs sm:text-sm font-medium border-b-2 border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 whitespace-nowrap" data-tab="categorias">\n          <i data-lucide="tags" class="w-4 h-4"></i>\n          <span>Categorias & Regras IA</span>\n        </button>\n      </nav>\n    </div>\n  </header>\n\n  <!-- CONTEÚDO PRINCIPAL -->\n  <main class="flex-1 max-w-7xl w-full mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">\n\n    <!-- BANNER DE ONBOARDING -->\n    <div id="banner-onboarding" class="hidden bg-gradient-to-r from-indigo-900/60 via-purple-900/50 to-slate-900/80 border border-indigo-500/30 p-5 rounded-2xl flex flex-col sm:flex-row items-center justify-between gap-4 shadow-lg shadow-indigo-950/30 fade-in">\n      <div class="flex items-center gap-3.5">\n        <div class="w-12 h-12 rounded-2xl bg-indigo-600/30 border border-indigo-400/30 flex items-center justify-center text-indigo-400 shrink-0">\n          <i data-lucide="sparkles" class="w-6 h-6"></i>\n        </div>\n        <div>\n          <h3 class="text-sm font-bold text-white">Sua base de dados está 100% pronta e zerada!</h3>\n          <p class="text-xs text-indigo-200/80 mt-0.5">Cadastre sua primeira conta bancária para começar a lançar despesas ou importe seu extrato (OFX/CSV) com 1 clique.</p>\n        </div>\n      </div>\n      <button id="btn-onboarding-conta" class="px-4 py-2.5 rounded-xl bg-indigo-600 hover:bg-indigo-500 text-white text-xs font-bold shadow-md shadow-indigo-600/40 transition whitespace-nowrap flex items-center gap-2">\n        <i data-lucide="plus" class="w-4 h-4"></i>\n        Cadastrar Primeira Conta\n      </button>\n    </div>\n\n    <!-- ============================================== -->\n    <!-- TAB 1: VISÃO GERAL (DASHBOARD) -->\n    <!-- ============================================== -->\n    <div id="tab-dashboard" class="tab-pane space-y-6 fade-in">\n      \n      <!-- 4 CARDS DE RESUMO FINANCEIRO -->\n      <div class="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">\n        \n        <!-- Card 1: Saldo Consolidado em Contas -->\n        <div class="stat-card bg-white dark:bg-slate-900/90 p-5 rounded-2xl border border-slate-200/80 dark:border-slate-800 shadow-sm relative overflow-hidden flex flex-col justify-between">\n          <div class="flex items-center justify-between">\n            <span class="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Saldo Consolidado</span>\n            <div class="w-9 h-9 rounded-xl bg-indigo-50 dark:bg-indigo-950/60 text-indigo-600 dark:text-indigo-400 flex items-center justify-center border border-indigo-100 dark:border-indigo-800/60">\n              <i data-lucide="wallet" class="w-4 h-4"></i>\n            </div>\n          </div>\n          <div class="mt-3">\n            <h3 id="card-saldo-total" class="text-2xl font-black text-slate-900 dark:text-white tracking-tight">R$ 0,00</h3>\n            <p class="text-xs text-slate-500 dark:text-slate-400 mt-1.5 flex items-center gap-1.5">\n              <span class="w-2 h-2 rounded-full bg-emerald-500 shrink-0"></span>\n              <span>Saldo real disponível</span>\n            </p>\n          </div>\n        </div>\n\n        <!-- Card 2: Receitas do Mês -->\n        <div class="stat-card bg-white dark:bg-slate-900/90 p-5 rounded-2xl border border-slate-200/80 dark:border-slate-800 shadow-sm relative overflow-hidden flex flex-col justify-between">\n          <div class="flex items-center justify-between">\n            <span class="text-xs font-semibold text-emerald-600 dark:text-emerald-400 uppercase tracking-wider">Receitas do Mês</span>\n            <div class="w-9 h-9 rounded-xl bg-emerald-50 dark:bg-emerald-950/60 text-emerald-600 dark:text-emerald-400 flex items-center justify-center border border-emerald-100 dark:border-emerald-800/60">\n              <i data-lucide="trending-up" class="w-4 h-4"></i>\n            </div>\n          </div>\n          <div class="mt-3">\n            <h3 id="card-receitas-total" class="text-2xl font-black text-emerald-600 dark:text-emerald-400 tracking-tight">R$ 0,00</h3>\n            <div class="flex items-center justify-between text-xs text-slate-500 dark:text-slate-400 mt-1.5">\n              <span class="flex items-center gap-1">\n                <span class="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>\n                <span>Recebidas: <b id="card-receitas-pagas" class="text-slate-700 dark:text-slate-200 font-semibold">R$ 0,00</b></span>\n              </span>\n              <span class="flex items-center gap-1">\n                <span class="w-1.5 h-1.5 rounded-full bg-amber-400"></span>\n                <span>A receber: <b id="card-receitas-pendentes" class="text-slate-700 dark:text-slate-200 font-semibold">R$ 0,00</b></span>\n              </span>\n            </div>\n          </div>\n        </div>\n\n        <!-- Card 3: Despesas do Mês -->\n        <div class="stat-card bg-white dark:bg-slate-900/90 p-5 rounded-2xl border border-slate-200/80 dark:border-slate-800 shadow-sm relative overflow-hidden flex flex-col justify-between">\n          <div class="flex items-center justify-between">\n            <span class="text-xs font-semibold text-rose-600 dark:text-rose-400 uppercase tracking-wider">Despesas do Mês</span>\n            <div class="w-9 h-9 rounded-xl bg-rose-50 dark:bg-rose-950/60 text-rose-600 dark:text-rose-400 flex items-center justify-center border border-rose-100 dark:border-rose-800/60">\n              <i data-lucide="trending-down" class="w-4 h-4"></i>\n            </div>\n          </div>\n          <div class="mt-3">\n            <h3 id="card-despesas-total" class="text-2xl font-black text-rose-600 dark:text-rose-400 tracking-tight">R$ 0,00</h3>\n            <div class="flex items-center justify-between text-xs text-slate-500 dark:text-slate-400 mt-1.5">\n              <span class="flex items-center gap-1">\n                <span class="w-1.5 h-1.5 rounded-full bg-rose-500"></span>\n                <span>Pagas: <b id="card-despesas-pagas" class="text-slate-700 dark:text-slate-200 font-semibold">R$ 0,00</b></span>\n              </span>\n              <span class="flex items-center gap-1">\n                <span class="w-1.5 h-1.5 rounded-full bg-amber-400"></span>\n                <span>Pendentes: <b id="card-despesas-pendentes" class="text-slate-700 dark:text-slate-200 font-semibold">R$ 0,00</b></span>\n              </span>\n            </div>\n          </div>\n        </div>\n\n        <!-- Card 4: Saldo Previsto no Fim do Mês -->\n        <div class="stat-card bg-white dark:bg-slate-900/90 p-5 rounded-2xl border border-slate-200/80 dark:border-slate-800 shadow-sm relative overflow-hidden flex flex-col justify-between">\n          <div class="flex items-center justify-between">\n            <span class="text-xs font-semibold text-slate-500 dark:text-slate-400 uppercase tracking-wider">Saldo Previsto (Fim do Mês)</span>\n            <div class="w-9 h-9 rounded-xl bg-cyan-50 dark:bg-cyan-950/60 text-cyan-600 dark:text-cyan-400 flex items-center justify-center border border-cyan-100 dark:border-cyan-800/60">\n              <i data-lucide="target" class="w-4 h-4"></i>\n            </div>\n          </div>\n          <div class="mt-3">\n            <h3 id="card-saldo-previsto" class="text-2xl font-black text-cyan-600 dark:text-cyan-400 tracking-tight">R$ 0,00</h3>\n            <p id="card-balanco-mes" class="text-xs text-slate-500 dark:text-slate-400 mt-1.5 flex items-center gap-1.5">\n              <span>Balanço mensal:</span> <b class="font-semibold text-slate-700 dark:text-slate-200">R$ 0,00</b>\n            </p>\n          </div>\n        </div>\n\n      </div>\n\n      <!-- SEÇÃO: MINHAS CONTAS BANCÁRIAS -->\n      <div class="space-y-3">\n        <div class="flex items-center justify-between">\n          <div class="flex items-center gap-2">\n            <i data-lucide="credit-card" class="w-5 h-5 text-indigo-500"></i>\n            <h2 class="text-base font-bold text-slate-900 dark:text-white">Minhas Contas e Carteiras</h2>\n          </div>\n          <div class="flex items-center gap-2">\n            <button id="btn-quick-import" class="text-xs flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-indigo-50 hover:bg-indigo-100 dark:bg-indigo-950/60 dark:hover:bg-indigo-900/60 text-indigo-600 dark:text-indigo-300 font-semibold transition border border-indigo-200/50 dark:border-indigo-800/40">\n              <i data-lucide="file-up" class="w-3.5 h-3.5"></i>\n              Importar Extrato\n            </button>\n            <button id="btn-quick-transfer" class="text-xs flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 font-semibold transition border border-slate-200/60 dark:border-slate-700/60">\n              <i data-lucide="arrow-left-right" class="w-3.5 h-3.5"></i>\n              Transferir\n            </button>\n            <button id="btn-quick-new-account" class="text-xs flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 text-slate-700 dark:text-slate-200 font-semibold transition border border-slate-200/60 dark:border-slate-700/60">\n              <i data-lucide="plus" class="w-3.5 h-3.5"></i>\n              Nova Conta\n            </button>\n          </div>\n        </div>\n\n        <div id="grid-contas-dashboard" class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">\n          <!-- Injetado dinamicamente -->\n        </div>\n      </div>\n\n      <!-- GRÁFICOS & ALERTAS -->\n      <div class="grid grid-cols-1 lg:grid-cols-3 gap-6">\n        \n        <!-- Gráfico 1: Despesas por Categoria (Rosca) -->\n        <div class="bg-white dark:bg-slate-900/90 p-5 rounded-2xl border border-slate-200/80 dark:border-slate-800 shadow-sm flex flex-col">\n          <div class="flex items-center justify-between mb-4">\n            <h3 class="text-sm font-bold text-slate-900 dark:text-white flex items-center gap-2">\n              <i data-lucide="pie-chart" class="w-4 h-4 text-indigo-500"></i>\n              Despesas por Categoria\n            </h3>\n            <span id="tag-mes-grafico" class="text-xs text-slate-500 dark:text-slate-400 font-medium"></span>\n          </div>\n          <div class="relative flex-1 flex items-center justify-center min-h-[240px]">\n            <canvas id="chart-categorias"></canvas>\n            <div id="chart-empty-msg" class="hidden absolute inset-0 flex flex-col items-center justify-center text-center p-4">\n              <i data-lucide="folder-open" class="w-8 h-8 text-slate-400 mb-2"></i>\n              <p class="text-xs text-slate-500 dark:text-slate-400">Nenhuma despesa registrada neste mês.</p>\n            </div>\n          </div>\n        </div>\n\n        <!-- Gráfico 2: Fluxo Mensal dos últimos 6 meses -->\n        <div class="bg-white dark:bg-slate-900/90 p-5 rounded-2xl border border-slate-200/80 dark:border-slate-800 shadow-sm flex flex-col">\n          <div class="flex items-center justify-between mb-4">\n            <h3 class="text-sm font-bold text-slate-900 dark:text-white flex items-center gap-2">\n              <i data-lucide="bar-chart-3" class="w-4 h-4 text-emerald-500"></i>\n              Fluxo dos Últimos 6 Meses\n            </h3>\n          </div>\n          <div class="relative flex-1 flex items-center justify-center min-h-[240px]">\n            <canvas id="chart-historico"></canvas>\n          </div>\n        </div>\n\n        <!-- Alertas: Contas a Vencer nos Próximos 7 Dias -->\n        <div class="bg-white dark:bg-slate-900/90 p-5 rounded-2xl border border-slate-200/80 dark:border-slate-800 shadow-sm flex flex-col">\n          <div class="flex items-center justify-between mb-4">\n            <h3 class="text-sm font-bold text-slate-900 dark:text-white flex items-center gap-2">\n              <i data-lucide="bell-ring" class="w-4 h-4 text-amber-500"></i>\n              A Vencer / Vencidas\n            </h3>\n            <span class="text-xs px-2 py-0.5 rounded-full bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-300 font-semibold" id="badge-alertas-count">0</span>\n          </div>\n\n          <div id="lista-alertas-dashboard" class="flex-1 space-y-2.5 overflow-y-auto max-h-[250px] pr-1">\n            <!-- Injetado dinamicamente -->\n          </div>\n        </div>\n\n      </div>\n\n    </div>\n\n    <!-- ============================================== -->\n    <!-- TAB 2: LANÇAMENTOS & EXTRATO -->\n    <!-- ============================================== -->\n    <div id="tab-transacoes" class="tab-pane hidden space-y-4 fade-in">\n      \n      <!-- BARRA DE FILTROS & AÇÃO DE ZERAR MÊS & IMPORTAR -->\n      <div class="bg-white dark:bg-slate-900 p-4 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm space-y-3">\n        <div class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-5 gap-3">\n          \n          <!-- Busca por texto -->\n          <div class="md:col-span-2 relative">\n            <i data-lucide="search" class="w-4 h-4 absolute left-3 top-3 text-slate-400"></i>\n            <input type="text" id="filtro-busca" placeholder="Buscar por descrição ou observação..." class="w-full pl-9 pr-3 py-2 text-xs sm:text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n          </div>\n\n          <!-- Filtro Conta -->\n          <div>\n            <select id="filtro-conta" class="w-full px-3 py-2 text-xs sm:text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n              <option value="">Todas as Contas</option>\n            </select>\n          </div>\n\n          <!-- Filtro Categoria -->\n          <div>\n            <select id="filtro-categoria" class="w-full px-3 py-2 text-xs sm:text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n              <option value="">Todas as Categorias</option>\n            </select>\n          </div>\n\n          <!-- Filtro Tipo / Status -->\n          <div class="flex gap-2">\n            <select id="filtro-tipo" class="w-1/2 px-2 py-2 text-xs bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n              <option value="">Tipo: Todos</option>\n              <option value="despesa">Despesas</option>\n              <option value="receita">Receitas</option>\n              <option value="transferencia">Transf.</option>\n            </select>\n\n            <select id="filtro-status" class="w-1/2 px-2 py-2 text-xs bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n              <option value="">Status: Todos</option>\n              <option value="pago">Pagas</option>\n              <option value="pendente">Pendentes</option>\n            </select>\n          </div>\n\n        </div>\n\n        <!-- Sub-resumo dos filtros e Ações de Importar e Zerar Mês -->\n        <div class="flex flex-col sm:flex-row items-center justify-between text-xs text-slate-500 dark:text-slate-400 pt-2 border-t border-slate-100 dark:border-slate-800 gap-2">\n          <div class="flex items-center gap-4">\n            <span>Total de registros: <b id="lbl-total-registros" class="text-slate-900 dark:text-white">0</b></span>\n            <span>Total filtrado: <b id="lbl-total-valor-filtrado" class="text-slate-900 dark:text-white">R$ 0,00</b></span>\n          </div>\n          \n          <div class="flex items-center gap-3">\n            <button id="btn-extrato-importar" class="flex items-center gap-1.5 text-indigo-600 dark:text-indigo-400 font-semibold hover:underline">\n              <i data-lucide="file-up" class="w-3.5 h-3.5"></i>\n              Importar Extrato OFX/CSV\n            </button>\n            <span class="text-slate-300 dark:text-slate-700">|</span>\n            <button id="btn-limpar-filtros" class="text-slate-600 dark:text-slate-400 hover:underline">Limpar Filtros</button>\n            <span class="text-slate-300 dark:text-slate-700">|</span>\n            <button id="btn-zerar-mes" class="flex items-center gap-1 text-rose-600 dark:text-rose-400 hover:text-rose-700 font-semibold transition hover:underline">\n              <i data-lucide="trash" class="w-3.5 h-3.5"></i>\n              Zerar Lançamentos deste Mês\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <!-- TABELA DE TRANSAÇÕES -->\n      <div class="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden">\n        <div class="overflow-x-auto">\n          <table class="w-full text-left text-xs sm:text-sm">\n            <thead class="bg-slate-50 dark:bg-slate-800/60 text-slate-500 dark:text-slate-400 font-semibold border-b border-slate-200 dark:border-slate-800">\n              <tr>\n                <th class="py-3.5 px-4">Data</th>\n                <th class="py-3.5 px-4">Descrição & Categoria</th>\n                <th class="py-3.5 px-4">Conta Bancária</th>\n                <th class="py-3.5 px-4 text-right">Valor</th>\n                <th class="py-3.5 px-4 text-center">Status / Baixa</th>\n                <th class="py-3.5 px-4 text-center">Ações</th>\n              </tr>\n            </thead>\n            <tbody id="tbody-transacoes" class="divide-y divide-slate-100 dark:divide-slate-800/80">\n              <!-- Injetado dinamicamente -->\n            </tbody>\n          </table>\n        </div>\n\n        <div id="transacoes-empty-msg" class="hidden p-12 text-center">\n          <div class="w-12 h-12 rounded-full bg-slate-100 dark:bg-slate-800 flex items-center justify-center mx-auto mb-3 text-slate-400">\n            <i data-lucide="inbox" class="w-6 h-6"></i>\n          </div>\n          <p class="text-sm font-semibold text-slate-700 dark:text-slate-300">Nenhum lançamento registrado neste mês</p>\n          <p class="text-xs text-slate-500 dark:text-slate-400 mt-1">Clique em "+ Novo Lançamento" ou "Importar Extrato" para adicionar suas movimentações.</p>\n        </div>\n      </div>\n\n    </div>\n\n    <!-- ============================================== -->\n    <!-- TAB 3: RECORRÊNCIAS & DESPESAS FIXAS -->\n    <!-- ============================================== -->\n    <div id="tab-recorrencias" class="tab-pane hidden space-y-4 fade-in">\n      <div class="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col sm:flex-row sm:items-center justify-between gap-4">\n        <div>\n          <h2 class="text-base font-bold text-slate-900 dark:text-white flex items-center gap-2">\n            <i data-lucide="refresh-cw" class="w-5 h-5 text-indigo-500"></i>\n            Despesas & Receitas Recorrentes (Fixas)\n          </h2>\n          <p class="text-xs text-slate-500 dark:text-slate-400 mt-1">\n            Cadastre contas que você paga todo mês (aluguel, condomínio, internet, assinaturas, salários) e defina a data de início!\n          </p>\n        </div>\n\n        <div class="flex items-center gap-2">\n          <button id="btn-force-generate-recurring" class="flex items-center gap-1.5 px-3 py-2 text-xs font-semibold text-slate-700 dark:text-slate-200 bg-slate-100 hover:bg-slate-200 dark:bg-slate-800 dark:hover:bg-slate-700 rounded-xl transition">\n            <i data-lucide="sparkles" class="w-4 h-4 text-amber-500"></i>\n            Sincronizar no Mês Atual\n          </button>\n          <button id="btn-modal-recorrencia" class="flex items-center gap-1.5 px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-md shadow-indigo-600/30 transition">\n            <i data-lucide="plus" class="w-4 h-4"></i>\n            Nova Recorrência\n          </button>\n        </div>\n      </div>\n\n      <!-- Tabela de Recorrências -->\n      <div class="bg-white dark:bg-slate-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden">\n        <div class="overflow-x-auto">\n          <table class="w-full text-left text-xs sm:text-sm">\n            <thead class="bg-slate-50 dark:bg-slate-800/60 text-slate-500 dark:text-slate-400 font-semibold border-b border-slate-200 dark:border-slate-800">\n              <tr>\n                <th class="py-3.5 px-4">Dia do Vencimento</th>\n                <th class="py-3.5 px-4">Descrição & Categoria</th>\n                <th class="py-3.5 px-4">Data de Início</th>\n                <th class="py-3.5 px-4">Conta Padrão</th>\n                <th class="py-3.5 px-4 text-right">Valor Estimado</th>\n                <th class="py-3.5 px-4 text-center">Ações</th>\n              </tr>\n            </thead>\n            <tbody id="tbody-recorrencias" class="divide-y divide-slate-100 dark:divide-slate-800/80">\n              <!-- Injetado via JS -->\n            </tbody>\n          </table>\n        </div>\n        <div id="recorrencias-empty-msg" class="hidden p-12 text-center">\n          <p class="text-xs text-slate-500 dark:text-slate-400">Nenhuma despesa ou receita fixa cadastrada ainda.</p>\n        </div>\n      </div>\n    </div>\n\n    <!-- ============================================== -->\n    <!-- TAB 4: CONTAS BANCÁRIAS -->\n    <!-- ============================================== -->\n    <div id="tab-contas" class="tab-pane hidden space-y-6 fade-in">\n      <div class="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col sm:flex-row sm:items-center justify-between gap-4">\n        <div>\n          <h2 class="text-base font-bold text-slate-900 dark:text-white flex items-center gap-2">\n            <i data-lucide="landmark" class="w-5 h-5 text-indigo-500"></i>\n            Gestão de Contas Bancárias & Carteiras\n          </h2>\n          <p class="text-xs text-slate-500 dark:text-slate-400 mt-1">\n            Cadastre suas contas correntes, contas digitais, poupança, carteira e investimentos para acompanhar seus saldos consolidados.\n          </p>\n        </div>\n\n        <div class="flex items-center gap-2">\n          <button id="btn-nova-conta-tab" class="flex items-center gap-1.5 px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-md shadow-indigo-600/30 transition">\n            <i data-lucide="plus" class="w-4 h-4"></i>\n            Cadastrar Nova Conta\n          </button>\n        </div>\n      </div>\n\n      <div id="grid-contas-gerenciamento" class="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-5">\n        <!-- Injetado via JS -->\n      </div>\n    </div>\n\n    <!-- ============================================== -->\n    <!-- TAB 5: CATEGORIAS & REGRAS INTELIGENTES -->\n    <!-- ============================================== -->\n    <div id="tab-categorias" class="tab-pane hidden space-y-6 fade-in">\n      <div class="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col sm:flex-row sm:items-center justify-between gap-4">\n        <div>\n          <h2 class="text-base font-bold text-slate-900 dark:text-white flex items-center gap-2">\n            <i data-lucide="tags" class="w-5 h-5 text-indigo-500"></i>\n            Categorias & Memória de Categorização Inteligente\n          </h2>\n          <p class="text-xs text-slate-500 dark:text-slate-400 mt-1">\n            Organize suas movimentações e veja os padrões que o FinFlow aprendeu para auto-categorizar seus extratos.\n          </p>\n        </div>\n\n        <button id="btn-nova-categoria-tab" class="flex items-center gap-1.5 px-4 py-2 text-xs font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-md shadow-indigo-600/30 transition">\n          <i data-lucide="plus" class="w-4 h-4"></i>\n          Nova Categoria\n        </button>\n      </div>\n\n      <!-- Grid de Categorias -->\n      <div class="grid grid-cols-1 md:grid-cols-2 gap-6">\n        <!-- Despesas -->\n        <div class="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm space-y-3">\n          <h3 class="text-sm font-bold text-rose-600 dark:text-rose-400 flex items-center gap-2">\n            <i data-lucide="arrow-down-circle" class="w-4 h-4"></i>\n            Categorias de Despesas\n          </h3>\n          <div id="lista-categorias-despesa" class="space-y-2"></div>\n        </div>\n\n        <!-- Receitas -->\n        <div class="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm space-y-3">\n          <h3 class="text-sm font-bold text-emerald-600 dark:text-emerald-400 flex items-center gap-2">\n            <i data-lucide="arrow-up-circle" class="w-4 h-4"></i>\n            Categorias de Receitas\n          </h3>\n          <div id="lista-categorias-receita" class="space-y-2"></div>\n        </div>\n      </div>\n\n      <!-- Memória de Regras Aprendidas da IA -->\n      <div class="bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm space-y-4">\n        <div class="flex items-center justify-between">\n          <div>\n            <h3 class="text-sm font-bold text-slate-900 dark:text-white flex items-center gap-2">\n              <i data-lucide="sparkles" class="w-4 h-4 text-indigo-500"></i>\n              Regras de Auto-Categorização Memorizadas\n            </h3>\n            <p class="text-xs text-slate-500 dark:text-slate-400 mt-0.5">\n              Padrões que você ensinou ao FinFlow durante as importações para reconhecer e classificar automaticamente.\n            </p>\n          </div>\n          <span id="badge-regras-count" class="text-xs px-2.5 py-1 rounded-full bg-indigo-50 dark:bg-indigo-950/60 text-indigo-600 dark:text-indigo-400 font-bold border border-indigo-200 dark:border-indigo-800/60">0 regras</span>\n        </div>\n\n        <div id="grid-regras-aprendidas" class="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-3">\n          <!-- Injetado dinamicamente -->\n        </div>\n      </div>\n\n    </div>\n\n  </main>\n\n  <!-- ============================================== -->\n  <!-- MODAL PRINCIPAL: IMPORTAÇÃO BANCÁRIA INTELIGENTE (OFX, CSV, TXT) -->\n  <!-- ============================================== -->\n  <div id="modal-import" class="fixed inset-0 z-50 flex items-center justify-center p-3 sm:p-4 modal-backdrop hidden">\n    <div class="bg-white dark:bg-slate-900 w-full max-w-4xl max-h-[90vh] rounded-2xl border border-slate-200 dark:border-slate-800 shadow-2xl overflow-hidden flex flex-col transform transition-all">\n      \n      <!-- Cabeçalho do Modal de Importação -->\n      <div class="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between bg-slate-50/50 dark:bg-slate-800/40">\n        <div class="flex items-center gap-3">\n          <div class="w-10 h-10 rounded-xl bg-gradient-to-tr from-indigo-600 to-violet-600 flex items-center justify-center text-white shadow-md shadow-indigo-600/30">\n            <i data-lucide="file-up" class="w-5 h-5"></i>\n          </div>\n          <div>\n            <h3 id="modal-import-titulo" class="text-base font-bold text-slate-900 dark:text-white flex items-center gap-2">\n              Importação Inteligente de Extrato Bancário\n              <span class="text-[10px] px-2 py-0.5 rounded-full bg-indigo-100 dark:bg-indigo-900/60 text-indigo-700 dark:text-indigo-300 font-bold uppercase tracking-wider">OFX / CSV / TXT</span>\n            </h3>\n            <p id="modal-import-subtitulo" class="text-xs text-slate-500 dark:text-slate-400">Envie o arquivo exportado do seu banco para pré-visualizar e categorizar com IA</p>\n          </div>\n        </div>\n\n        <button class="btn-close-modal text-slate-400 hover:text-slate-600 dark:hover:text-slate-200 p-1.5 rounded-lg hover:bg-slate-100 dark:hover:bg-slate-800">\n          <i data-lucide="x" class="w-5 h-5"></i>\n        </button>\n      </div>\n\n      <!-- ETAPA 1: UPLOAD DO ARQUIVO -->\n      <div id="import-etapa-1" class="p-6 space-y-5 overflow-y-auto">\n        <div class="space-y-4">\n          <!-- Seleção de Conta -->\n          <div>\n            <label class="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">1. Selecione a Conta Bancária de Destino *</label>\n            <select id="import-conta-id" required class="w-full px-3.5 py-2.5 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n              <!-- Preenchido dinamicamente -->\n            </select>\n          </div>\n\n          <!-- Dropzone -->\n          <div>\n            <label class="block text-xs font-bold text-slate-700 dark:text-slate-300 mb-1.5">2. Selecione ou arraste o arquivo do extrato *</label>\n            <div id="import-dropzone" class="border-2 border-dashed border-slate-300 dark:border-slate-700 hover:border-indigo-500 dark:hover:border-indigo-400 rounded-2xl p-8 text-center cursor-pointer transition bg-slate-50/50 dark:bg-slate-800/20 group">\n              <input type="file" id="import-file-input" accept=".ofx,.csv,.txt" class="hidden">\n              <div class="w-14 h-14 rounded-2xl bg-indigo-50 dark:bg-indigo-950/60 text-indigo-600 dark:text-indigo-400 flex items-center justify-center mx-auto mb-3 group-hover:scale-110 transition">\n                <i data-lucide="upload-cloud" class="w-7 h-7"></i>\n              </div>\n              <p class="text-sm font-bold text-slate-800 dark:text-slate-200">Arraste seu arquivo OFX ou CSV aqui</p>\n              <p class="text-xs text-slate-500 dark:text-slate-400 mt-1">ou clique para procurar no seu computador</p>\n              \n              <div class="flex flex-wrap items-center justify-center gap-2 mt-4">\n                <span class="text-[11px] px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-medium">.OFX (Nubank, Itaú, Bradesco, BB, Inter, Santander, Caixa...)</span>\n                <span class="text-[11px] px-2.5 py-1 rounded-lg bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-300 font-medium">.CSV / .TXT</span>\n              </div>\n            </div>\n          </div>\n\n          <!-- Indicador de Arquivo Selecionado -->\n          <div id="import-selected-file-info" class="hidden p-3.5 rounded-xl bg-indigo-50 dark:bg-indigo-950/50 border border-indigo-200 dark:border-indigo-800/70 flex items-center justify-between">\n            <div class="flex items-center gap-3">\n              <i data-lucide="file-check-2" class="w-5 h-5 text-indigo-600 dark:text-indigo-400"></i>\n              <div>\n                <p id="import-file-name" class="text-xs font-bold text-indigo-950 dark:text-indigo-200">extrato.ofx</p>\n                <p id="import-file-size" class="text-[10px] text-indigo-600 dark:text-indigo-400">12.5 KB</p>\n              </div>\n            </div>\n            <button id="btn-import-process-file" class="px-4 py-2 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-md shadow-indigo-600/30 transition flex items-center gap-1.5">\n              <span>Analisar e Pré-visualizar</span>\n              <i data-lucide="arrow-right" class="w-3.5 h-3.5"></i>\n            </button>\n          </div>\n        </div>\n      </div>\n\n      <!-- ETAPA 2: CONFERÊNCIA & EDIÇÃO INTERATIVA COM SUGESTÃO IA -->\n      <div id="import-etapa-2" class="hidden flex-1 flex flex-col overflow-hidden">\n        \n        <!-- Barra de Resumo e Filtros da Prévia -->\n        <div class="p-4 bg-slate-50 dark:bg-slate-800/60 border-b border-slate-200 dark:border-slate-800 flex flex-col sm:flex-row sm:items-center justify-between gap-3 text-xs">\n          <div class="flex flex-wrap items-center gap-3">\n            <span class="font-bold text-slate-900 dark:text-white" id="import-preview-stats">0 transações</span>\n            <span class="text-emerald-500 font-semibold" id="import-preview-rec">+R$ 0,00</span>\n            <span class="text-rose-500 font-semibold" id="import-preview-desp">-R$ 0,00</span>\n          </div>\n\n          <div class="flex items-center gap-2">\n            <button id="btn-import-select-all" class="px-2.5 py-1 rounded-lg bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200 border border-slate-200 dark:border-slate-600 font-medium hover:bg-slate-100">\n              Selecionar Todas\n            </button>\n            <button id="btn-import-unselect-all" class="px-2.5 py-1 rounded-lg bg-white dark:bg-slate-700 text-slate-700 dark:text-slate-200 border border-slate-200 dark:border-slate-600 font-medium hover:bg-slate-100">\n              Desmarcar Todas\n            </button>\n          </div>\n        </div>\n\n        <!-- Tabela de Conferência com Scroll -->\n        <div class="flex-1 overflow-y-auto p-4">\n          <table class="w-full text-left text-xs">\n            <thead class="sticky top-0 bg-white dark:bg-slate-900 text-slate-500 dark:text-slate-400 font-semibold border-b border-slate-200 dark:border-slate-800 z-10">\n              <tr>\n                <th class="py-2.5 px-3 w-10 text-center">Importar</th>\n                <th class="py-2.5 px-3">Data</th>\n                <th class="py-2.5 px-3">Descrição Bancária</th>\n                <th class="py-2.5 px-3 text-right">Valor</th>\n                <th class="py-2.5 px-3">Categoria (Sugestão IA)</th>\n                <th class="py-2.5 px-3 text-center" title="Memorizar categoria para próximas importações">🧠 Lembrar</th>\n              </tr>\n            </thead>\n            <tbody id="tbody-import-preview" class="divide-y divide-slate-100 dark:divide-slate-800">\n              <!-- Injetado dinamicamente via JS -->\n            </tbody>\n          </table>\n        </div>\n\n        <!-- Rodapé de Ações da Importação -->\n        <div class="p-4 border-t border-slate-200 dark:border-slate-800 bg-white dark:bg-slate-900 flex items-center justify-between gap-3">\n          <button id="btn-import-voltar" class="px-4 py-2 text-xs font-semibold text-slate-600 dark:text-slate-300 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition flex items-center gap-1.5">\n            <i data-lucide="arrow-left" class="w-4 h-4"></i>\n            <span>Voltar / Escolher outro arquivo</span>\n          </button>\n\n          <button id="btn-import-confirmar-final" class="px-5 py-2.5 text-xs font-bold text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-lg shadow-indigo-600/30 transition flex items-center gap-2">\n            <i data-lucide="check-check" class="w-4 h-4"></i>\n            <span id="lbl-btn-confirm-import">Confirmar Importação</span>\n          </button>\n        </div>\n\n      </div>\n\n    </div>\n  </div>\n\n  <!-- MODAL: LANÇAMENTO RÁPIDO -->\n  <div id="modal-lancamento" class="fixed inset-0 z-50 flex items-center justify-center p-4 modal-backdrop hidden">\n    <div class="bg-white dark:bg-slate-900 w-full max-w-lg rounded-2xl border border-slate-200 dark:border-slate-800 shadow-2xl overflow-hidden transform transition-all">\n      <div class="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">\n        <h3 id="modal-lancamento-titulo" class="text-base font-bold text-slate-900 dark:text-white">Novo Lançamento</h3>\n        <button class="btn-close-modal text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">\n          <i data-lucide="x" class="w-5 h-5"></i>\n        </button>\n      </div>\n\n      <form id="form-lancamento" class="p-5 space-y-4">\n        <input type="hidden" id="lancamento-id" value="">\n\n        <div class="grid grid-cols-3 gap-2 bg-slate-100 dark:bg-slate-800/80 p-1 rounded-xl">\n          <button type="button" class="btn-tipo-transacao py-2 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1.5 bg-rose-600 text-white shadow-sm" data-tipo="despesa">\n            <i data-lucide="arrow-down-right" class="w-3.5 h-3.5"></i>\n            Despesa\n          </button>\n          <button type="button" class="btn-tipo-transacao py-2 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1.5 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white" data-tipo="receita">\n            <i data-lucide="arrow-up-right" class="w-3.5 h-3.5"></i>\n            Receita\n          </button>\n          <button type="button" class="btn-tipo-transacao py-2 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1.5 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white" data-tipo="transferencia">\n            <i data-lucide="arrow-left-right" class="w-3.5 h-3.5"></i>\n            Transferência\n          </button>\n        </div>\n\n        <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Descrição *</label>\n            <input type="text" id="lancamento-descricao" required placeholder="Ex: Supermercado, Aluguel..." class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n          </div>\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Valor (R$) *</label>\n            <div class="relative">\n              <span class="absolute left-3 top-2 text-sm font-bold text-slate-400">R$</span>\n              <input type="number" step="0.01" min="0.01" id="lancamento-valor" required placeholder="0,00" class="w-full pl-10 pr-3 py-2 text-sm font-bold bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n            </div>\n          </div>\n        </div>\n\n        <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Data *</label>\n            <input type="date" id="lancamento-data" required class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n          </div>\n          <div id="container-campo-status">\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Status da Movimentação</label>\n            <select id="lancamento-status" class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n              <option value="pago">Pago / Realizado (Debita/Credita do Saldo)</option>\n              <option value="pendente">Pendente / A Vencer (Agendado)</option>\n            </select>\n          </div>\n        </div>\n\n        <div class="grid grid-cols-1 sm:grid-cols-2 gap-3">\n          <div>\n            <label id="lbl-conta-origem" class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Conta Bancária *</label>\n            <select id="lancamento-conta" required class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n            </select>\n          </div>\n\n          <div id="container-conta-destino" class="hidden">\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Conta de Destino *</label>\n            <select id="lancamento-conta-destino" class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n            </select>\n          </div>\n\n          <div id="container-categoria">\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Categoria</label>\n            <select id="lancamento-categoria" class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n            </select>\n          </div>\n        </div>\n\n        <div>\n          <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Observações (opcional)</label>\n          <input type="text" id="lancamento-observacoes" placeholder="Ex: Pago no débito, comprovante no e-mail..." class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n        </div>\n\n        <div class="pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-end gap-2">\n          <button type="button" class="btn-close-modal px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition">\n            Cancelar\n          </button>\n          <button type="submit" class="px-5 py-2 text-sm font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-md shadow-indigo-600/30 transition">\n            Salvar Lançamento\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- MODAL: NOVA / EDITAR CONTA BANCÁRIA -->\n  <div id="modal-conta" class="fixed inset-0 z-50 flex items-center justify-center p-4 modal-backdrop hidden">\n    <div class="bg-white dark:bg-slate-900 w-full max-w-md rounded-2xl border border-slate-200 dark:border-slate-800 shadow-2xl overflow-hidden">\n      <div class="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">\n        <h3 id="modal-conta-titulo" class="text-base font-bold text-slate-900 dark:text-white">Nova Conta Bancária</h3>\n        <button class="btn-close-modal text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">\n          <i data-lucide="x" class="w-5 h-5"></i>\n        </button>\n      </div>\n\n      <form id="form-conta" class="p-5 space-y-4">\n        <input type="hidden" id="conta-id" value="">\n\n        <div>\n          <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Nome de Identificação *</label>\n          <input type="text" id="conta-nome" required placeholder="Ex: Nubank, Carteira, Itaú Principal..." class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n        </div>\n\n        <div class="grid grid-cols-2 gap-3">\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Instituição / Banco</label>\n            <input type="text" id="conta-instituicao" placeholder="Ex: Nubank, Itaú..." class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n          </div>\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Tipo de Conta</label>\n            <select id="conta-tipo" class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n              <option value="Corrente">Conta Corrente</option>\n              <option value="Poupança">Poupança</option>\n              <option value="Carteira">Carteira (Dinheiro)</option>\n              <option value="Investimento">Investimento</option>\n              <option value="Outros">Outros</option>\n            </select>\n          </div>\n        </div>\n\n        <div class="grid grid-cols-2 gap-3">\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Saldo Inicial (R$)</label>\n            <input type="number" step="0.01" id="conta-saldo-inicial" placeholder="0,00" class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n          </div>\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Cor do Card</label>\n            <div class="flex items-center gap-2">\n              <input type="color" id="conta-cor" value="#3b82f6" class="h-9 w-12 rounded-lg cursor-pointer bg-transparent border-0">\n              <span id="conta-cor-label" class="text-xs font-mono text-slate-500">#3b82f6</span>\n            </div>\n          </div>\n        </div>\n\n        <div class="pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-end gap-2">\n          <button type="button" class="btn-close-modal px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition">\n            Cancelar\n          </button>\n          <button type="submit" class="px-5 py-2 text-sm font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-md shadow-indigo-600/30 transition">\n            Salvar Conta\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- MODAL: TRANSFERÊNCIA RÁPIDA -->\n  <div id="modal-transferencia" class="fixed inset-0 z-50 flex items-center justify-center p-4 modal-backdrop hidden">\n    <div class="bg-white dark:bg-slate-900 w-full max-w-md rounded-2xl border border-slate-200 dark:border-slate-800 shadow-2xl overflow-hidden">\n      <div class="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">\n        <h3 class="text-base font-bold text-slate-900 dark:text-white flex items-center gap-2">\n          <i data-lucide="arrow-left-right" class="w-4 h-4 text-indigo-500"></i>\n          Transferir entre Contas\n        </h3>\n        <button class="btn-close-modal text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">\n          <i data-lucide="x" class="w-5 h-5"></i>\n        </button>\n      </div>\n\n      <form id="form-transferencia-modal" class="p-5 space-y-4">\n        <div class="grid grid-cols-2 gap-3">\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">De (Origem) *</label>\n            <select id="transf-origem" required class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n            </select>\n          </div>\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Para (Destino) *</label>\n            <select id="transf-destino" required class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n            </select>\n          </div>\n        </div>\n\n        <div class="grid grid-cols-2 gap-3">\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Valor (R$) *</label>\n            <input type="number" step="0.01" min="0.01" id="transf-valor" required placeholder="0,00" class="w-full px-3 py-2 text-sm font-bold bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n          </div>\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Data *</label>\n            <input type="date" id="transf-data" required class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n          </div>\n        </div>\n\n        <div>\n          <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Descrição / Motivo</label>\n          <input type="text" id="transf-descricao" value="Transferência entre contas" class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n        </div>\n\n        <div class="pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-end gap-2">\n          <button type="button" class="btn-close-modal px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition">\n            Cancelar\n          </button>\n          <button type="submit" class="px-5 py-2 text-sm font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-md shadow-indigo-600/30 transition">\n            Confirmar Transferência\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- MODAL: NOVA / EDITAR RECORRÊNCIA -->\n  <div id="modal-recorrencia" class="fixed inset-0 z-50 flex items-center justify-center p-4 modal-backdrop hidden">\n    <div class="bg-white dark:bg-slate-900 w-full max-w-md rounded-2xl border border-slate-200 dark:border-slate-800 shadow-2xl overflow-hidden">\n      <div class="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">\n        <h3 id="modal-rec-titulo" class="text-base font-bold text-slate-900 dark:text-white">Nova Despesa / Receita Recorrente</h3>\n        <button class="btn-close-modal text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">\n          <i data-lucide="x" class="w-5 h-5"></i>\n        </button>\n      </div>\n\n      <form id="form-recorrencia" class="p-5 space-y-4">\n        <input type="hidden" id="rec-id" value="">\n\n        <div>\n          <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Tipo *</label>\n          <div class="grid grid-cols-2 gap-2 bg-slate-100 dark:bg-slate-800 p-1 rounded-xl">\n            <button type="button" class="btn-rec-tipo py-1.5 rounded-lg text-xs font-bold transition bg-rose-600 text-white" data-tipo="despesa">\n              Despesa Fixa\n            </button>\n            <button type="button" class="btn-rec-tipo py-1.5 rounded-lg text-xs font-bold transition text-slate-600 dark:text-slate-400" data-tipo="receita">\n              Receita Fixa\n            </button>\n          </div>\n        </div>\n\n        <div>\n          <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Descrição *</label>\n          <input type="text" id="rec-descricao" required placeholder="Ex: Aluguel, Internet, Netflix, Salário..." class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n        </div>\n\n        <div class="grid grid-cols-2 gap-3">\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Data de Início *</label>\n            <input type="date" id="rec-data-inicio" required class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n          </div>\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Término (Opcional)</label>\n            <input type="date" id="rec-data-fim" class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n          </div>\n        </div>\n\n        <div class="grid grid-cols-2 gap-3">\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Valor Estimado (R$) *</label>\n            <input type="number" step="0.01" min="0.01" id="rec-valor" required placeholder="0,00" class="w-full px-3 py-2 text-sm font-bold bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n          </div>\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Dia do Vencimento (1 a 31) *</label>\n            <input type="number" min="1" max="31" id="rec-dia" required value="5" class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n          </div>\n        </div>\n\n        <div class="grid grid-cols-2 gap-3">\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Conta Padrão</label>\n            <select id="rec-conta" class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n            </select>\n          </div>\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Categoria</label>\n            <select id="rec-categoria" class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n            </select>\n          </div>\n        </div>\n\n        <div class="pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-end gap-2">\n          <button type="button" class="btn-close-modal px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition">\n            Cancelar\n          </button>\n          <button type="submit" class="px-5 py-2 text-sm font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-md shadow-indigo-600/30 transition">\n            Salvar Recorrência\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- MODAL: NOVA CATEGORIA -->\n  <div id="modal-categoria" class="fixed inset-0 z-50 flex items-center justify-center p-4 modal-backdrop hidden">\n    <div class="bg-white dark:bg-slate-900 w-full max-w-sm rounded-2xl border border-slate-200 dark:border-slate-800 shadow-2xl overflow-hidden">\n      <div class="p-5 border-b border-slate-100 dark:border-slate-800 flex items-center justify-between">\n        <h3 class="text-base font-bold text-slate-900 dark:text-white">Nova Categoria</h3>\n        <button class="btn-close-modal text-slate-400 hover:text-slate-600 dark:hover:text-slate-200">\n          <i data-lucide="x" class="w-5 h-5"></i>\n        </button>\n      </div>\n\n      <form id="form-categoria" class="p-5 space-y-4">\n        <div>\n          <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Nome da Categoria *</label>\n          <input type="text" id="cat-nome" required placeholder="Ex: Streaming, Viagens, Pets..." class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n        </div>\n\n        <div class="grid grid-cols-2 gap-3">\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Tipo</label>\n            <select id="cat-tipo" class="w-full px-3 py-2 text-sm bg-slate-50 dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-xl focus:ring-2 focus:ring-indigo-500 focus:outline-none dark:text-white">\n              <option value="despesa">Despesa</option>\n              <option value="receita">Receita</option>\n            </select>\n          </div>\n          <div>\n            <label class="block text-xs font-semibold text-slate-700 dark:text-slate-300 mb-1">Cor</label>\n            <input type="color" id="cat-cor" value="#6366f1" class="h-9 w-full rounded-lg cursor-pointer bg-transparent border-0">\n          </div>\n        </div>\n\n        <div class="pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-end gap-2">\n          <button type="button" class="btn-close-modal px-4 py-2 text-sm font-medium text-slate-600 dark:text-slate-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-xl transition">\n            Cancelar\n          </button>\n          <button type="submit" class="px-5 py-2 text-sm font-semibold text-white bg-indigo-600 hover:bg-indigo-700 rounded-xl shadow-md shadow-indigo-600/30 transition">\n            Criar Categoria\n          </button>\n        </div>\n      </form>\n    </div>\n  </div>\n\n  <!-- RODAPÉ -->\n  <footer class="bg-white dark:bg-slate-900 border-t border-slate-200 dark:border-slate-800 py-4 text-center text-xs text-slate-500 dark:text-slate-400">\n    <div class="max-w-7xl mx-auto px-4 flex flex-col sm:flex-row items-center justify-between gap-2">\n      <div class="flex items-center gap-1.5">\n        <span class="font-semibold text-slate-700 dark:text-slate-300">FinFlow</span> &bull; Gestão Financeira Pessoal Inteligente\n      </div>\n      <div>\n        Pressione <kbd class="kbd-shortcut">N</kbd> para Novo Lançamento ou <kbd class="kbd-shortcut">I</kbd> para Importar Extrato.\n      </div>\n    </div>\n  </footer>\n\n  <!-- Script Principal -->\n  <script src="/static/js/app.js"></script>\n</body>\n</html>\n'

STYLES_CSS = "/* ========================================================\n   FinFlow - Design System & Custom Styles\n   ======================================================== */\n\n:root {\n  --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, sans-serif;\n}\n\nbody {\n  font-family: var(--font-sans);\n  -webkit-font-smoothing: antialiased;\n  -moz-osx-font-smoothing: grayscale;\n}\n\n/* Custom Scrollbars */\n::-webkit-scrollbar {\n  width: 6px;\n  height: 6px;\n}\n::-webkit-scrollbar-track {\n  background: transparent;\n}\n::-webkit-scrollbar-thumb {\n  background: rgba(156, 163, 175, 0.3);\n  border-radius: 9999px;\n}\n::-webkit-scrollbar-thumb:hover {\n  background: rgba(156, 163, 175, 0.6);\n}\n.dark ::-webkit-scrollbar-thumb {\n  background: rgba(71, 85, 105, 0.4);\n}\n.dark ::-webkit-scrollbar-thumb:hover {\n  background: rgba(71, 85, 105, 0.7);\n}\n\n/* Animações suaves */\n.fade-in {\n  animation: fadeIn 0.22s cubic-bezier(0.16, 1, 0.3, 1) forwards;\n}\n\n@keyframes fadeIn {\n  from {\n    opacity: 0;\n    transform: translateY(6px);\n  }\n  to {\n    opacity: 1;\n    transform: translateY(0);\n  }\n}\n\n/* Card Elevation & Hover */\n.stat-card {\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n}\n.stat-card:hover {\n  transform: translateY(-2px);\n}\n\n/* Cards de Conta Bancária */\n.bank-card {\n  transition: all 0.2s cubic-bezier(0.16, 1, 0.3, 1);\n  position: relative;\n  overflow: hidden;\n}\n.bank-card:hover {\n  transform: translateY(-2px);\n  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.05), 0 8px 10px -6px rgba(0, 0, 0, 0.05);\n}\n.dark .bank-card:hover {\n  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.3), 0 8px 10px -6px rgba(0, 0, 0, 0.3);\n}\n.bank-card::after {\n  content: '';\n  position: absolute;\n  top: 0;\n  left: 0;\n  right: 0;\n  height: 3px;\n  background: var(--account-color, #4f46e5);\n  border-top-left-radius: 1rem;\n  border-top-right-radius: 1rem;\n}\n\n/* Badges e Status Pills */\n.status-pill {\n  display: inline-flex;\n  align-items: center;\n  gap: 0.35rem;\n  padding: 0.25rem 0.65rem;\n  border-radius: 9999px;\n  font-size: 0.75rem;\n  font-weight: 600;\n  transition: all 0.15s ease;\n}\n\n.status-pago {\n  background-color: rgba(16, 185, 129, 0.12);\n  color: #059669;\n  border: 1px solid rgba(16, 185, 129, 0.25);\n}\n.dark .status-pago {\n  background-color: rgba(16, 185, 129, 0.18);\n  color: #34d399;\n  border: 1px solid rgba(52, 211, 153, 0.3);\n}\n\n.status-pendente {\n  background-color: rgba(245, 158, 11, 0.12);\n  color: #d97706;\n  border: 1px solid rgba(245, 158, 11, 0.25);\n}\n.dark .status-pendente {\n  background-color: rgba(245, 158, 11, 0.18);\n  color: #fbbf24;\n  border: 1px solid rgba(251, 191, 36, 0.3);\n}\n\n/* Modais */\n.modal-backdrop {\n  background-color: rgba(15, 23, 42, 0.65);\n  backdrop-filter: blur(4px);\n}\n\n/* Indicadores de atalhos de teclado */\n.kbd-shortcut {\n  font-family: ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;\n  font-size: 0.7rem;\n  padding: 0.1rem 0.35rem;\n  border-radius: 0.25rem;\n  background-color: rgba(0, 0, 0, 0.06);\n  border: 1px solid rgba(0, 0, 0, 0.1);\n}\n.dark .kbd-shortcut {\n  background-color: rgba(255, 255, 255, 0.1);\n  border: 1px solid rgba(255, 255, 255, 0.15);\n}\n"

APP_JS = '/**\n * FinFlow - Aplicação de Gestão Financeira Pessoal\n * Controlador SPA com Importação Inteligente de Extratos (OFX/CSV/TXT),\n * Conferência Interativa, Auto-Categorização com IA e Memória Contínua.\n */\n\n// Estado Global da Aplicação\nconst state = {\n  user: null,\n  currentDate: new Date(),\n  selectedMonth: new Date().getMonth() + 1, // 1-12\n  selectedYear: new Date().getFullYear(),\n  activeTab: \'dashboard\',\n  currentTipoLancamento: \'despesa\',\n  currentRecTipo: \'despesa\',\n  contas: [],\n  categorias: [],\n  transacoes: [],\n  recorrencias: [],\n  regrasAprendidas: [],\n  // Estado de Importação de Arquivo\n  import: {\n    selectedFile: null,\n    contaId: null,\n    previewTransactions: []\n  },\n  charts: {\n    categorias: null,\n    historico: null\n  }\n};\n\nconst nomesMeses = [\n  "", "Janeiro", "Fevereiro", "Março", "Abril", "Maio", "Junho",\n  "Julho", "Agosto", "Setembro", "Outubro", "Novembro", "Dezembro"\n];\n\n// Utilitário de Formatação de Moeda BRL\nfunction formatBRL(val) {\n  const num = parseFloat(val) || 0;\n  return num.toLocaleString(\'pt-BR\', { style: \'currency\', currency: \'BRL\' });\n}\n\n// Formatar data YYYY-MM-DD para DD/MM/YYYY\nfunction formatDateBR(dateStr) {\n  if (!dateStr) return \'\';\n  const parts = dateStr.split(\'-\');\n  if (parts.length === 3) {\n    return `${parts[2]}/${parts[1]}/${parts[0]}`;\n  }\n  return dateStr;\n}\n\n// Inicialização ao carregar a página\ndocument.addEventListener(\'DOMContentLoaded\', async () => {\n  lucide.createIcons();\n  initTheme();\n  \n  // 1. Verificar autenticação\n  const isAuth = await checkAuth();\n  if (!isAuth) return;\n\n  setupEventListeners();\n  setupImportEventListeners();\n  updateMonthYearLabel();\n\n  // 2. Carregar dados iniciais do usuário\n  await loadAllData();\n});\n\n// ========================================================\n// VERIFICAÇÃO DE AUTENTICAÇÃO & USUÁRIO\n// ========================================================\nasync function checkAuth() {\n  try {\n    const res = await fetch(\'/api/auth/me\');\n    if (!res.ok) {\n      window.location.href = \'/login\';\n      return false;\n    }\n    const data = await res.json();\n    state.user = data.user;\n\n    const nomeEl = document.getElementById(\'user-nome-label\');\n    const emailEl = document.getElementById(\'user-email-label\');\n    const avatarEl = document.getElementById(\'user-avatar-img\');\n\n    if (nomeEl) nomeEl.textContent = state.user.nome;\n    if (emailEl) emailEl.textContent = state.user.email;\n    if (avatarEl) {\n      avatarEl.src = state.user.avatar_url || `https://ui-avatars.com/api/?name=${encodeURIComponent(state.user.nome)}&background=6366f1&color=fff`;\n    }\n\n    return true;\n  } catch (err) {\n    window.location.href = \'/login\';\n    return false;\n  }\n}\n\nasync function handleLogout() {\n  const result = await Swal.fire({\n    title: \'Sair do FinFlow?\',\n    text: \'Sua sessão será encerrada com segurança.\',\n    icon: \'question\',\n    showCancelButton: true,\n    confirmButtonColor: \'#4f46e5\',\n    cancelButtonColor: \'#64748b\',\n    confirmButtonText: \'Sim, sair\',\n    cancelButtonText: \'Cancelar\'\n  });\n\n  if (result.isConfirmed) {\n    try {\n      await fetch(\'/api/auth/logout\', { method: \'POST\' });\n      window.location.href = \'/login\';\n    } catch (err) {\n      window.location.href = \'/login\';\n    }\n  }\n}\n\n// ========================================================\n// CONTROLE DE TEMA (DARK / LIGHT MODE)\n// ========================================================\nfunction initTheme() {\n  const savedTheme = localStorage.getItem(\'finflow_theme\') || \'dark\';\n  if (savedTheme === \'dark\') {\n    document.documentElement.classList.add(\'dark\');\n  } else {\n    document.documentElement.classList.remove(\'dark\');\n  }\n  updateThemeIcon();\n}\n\nfunction toggleTheme() {\n  const isDark = document.documentElement.classList.toggle(\'dark\');\n  localStorage.setItem(\'finflow_theme\', isDark ? \'dark\' : \'light\');\n  updateThemeIcon();\n  \n  if (state.activeTab === \'dashboard\') {\n    loadDashboard();\n  }\n}\n\nfunction updateThemeIcon() {\n  const isDark = document.documentElement.classList.contains(\'dark\');\n  const btn = document.getElementById(\'btn-toggle-theme\');\n  if (btn) {\n    btn.innerHTML = `<i data-lucide="${isDark ? \'sun\' : \'moon\'}" class="w-5 h-5"></i>`;\n    btn.setAttribute(\'title\', isDark ? \'Mudar para tema claro\' : \'Mudar para tema escuro\');\n    lucide.createIcons();\n  }\n}\n\n// ========================================================\n// CONTROLE DO SELETOR DE MÊS E ANO\n// ========================================================\nfunction updateMonthYearLabel() {\n  const label = document.getElementById(\'label-mes-ano\');\n  if (label) {\n    label.textContent = `${nomesMeses[state.selectedMonth]} / ${state.selectedYear}`;\n  }\n\n  const btnExport = document.getElementById(\'btn-export-csv\');\n  if (btnExport) {\n    btnExport.href = `/api/export/csv?mes=${state.selectedMonth}&ano=${state.selectedYear}`;\n  }\n\n  const tagMes = document.getElementById(\'tag-mes-grafico\');\n  if (tagMes) {\n    tagMes.textContent = `${nomesMeses[state.selectedMonth]}/${state.selectedYear}`;\n  }\n}\n\nfunction changeMonth(delta) {\n  state.selectedMonth += delta;\n  if (state.selectedMonth > 12) {\n    state.selectedMonth = 1;\n    state.selectedYear += 1;\n  } else if (state.selectedMonth < 1) {\n    state.selectedMonth = 12;\n    state.selectedYear -= 1;\n  }\n  updateMonthYearLabel();\n  loadAllData();\n}\n\nfunction resetToCurrentMonth() {\n  const now = new Date();\n  state.selectedMonth = now.getMonth() + 1;\n  state.selectedYear = now.getFullYear();\n  updateMonthYearLabel();\n  loadAllData();\n}\n\n// ========================================================\n// CARREGAMENTO CENTRALIZADO DE DADOS\n// ========================================================\nasync function loadAllData() {\n  await Promise.all([\n    fetchContas(),\n    fetchCategorias(),\n    fetchRegrasAprendidas()\n  ]);\n\n  const onboardingEl = document.getElementById(\'banner-onboarding\');\n  if (onboardingEl) {\n    if (state.contas.length === 0) {\n      onboardingEl.classList.remove(\'hidden\');\n    } else {\n      onboardingEl.classList.add(\'hidden\');\n    }\n  }\n\n  if (state.activeTab === \'dashboard\') {\n    loadDashboard();\n  } else if (state.activeTab === \'transacoes\') {\n    loadTransacoes();\n  } else if (state.activeTab === \'recorrencias\') {\n    loadRecorrencias();\n  } else if (state.activeTab === \'contas\') {\n    renderContasTab();\n  } else if (state.activeTab === \'categorias\') {\n    renderCategoriasTab();\n  }\n}\n\n// ========================================================\n// REQUISIÇÕES BÁSICAS: CONTAS & CATEGORIAS & REGRAS\n// ========================================================\nasync function fetchContas() {\n  try {\n    const res = await fetch(\'/api/contas\');\n    if (res.status === 401) { window.location.href = \'/login\'; return; }\n    state.contas = await res.json();\n    populateContasSelects();\n  } catch (err) {\n    console.error(\'Erro ao buscar contas:\', err);\n  }\n}\n\nasync function fetchCategorias() {\n  try {\n    const res = await fetch(\'/api/categorias\');\n    if (res.status === 401) { window.location.href = \'/login\'; return; }\n    state.categorias = await res.json();\n    populateCategoriasSelects();\n  } catch (err) {\n    console.error(\'Erro ao buscar categorias:\', err);\n  }\n}\n\nasync function fetchRegrasAprendidas() {\n  try {\n    const res = await fetch(\'/api/regras-categorizacao\');\n    if (res.status === 401) return;\n    state.regrasAprendidas = await res.json();\n    renderRegrasAprendidasGrid();\n  } catch (err) {\n    console.error(\'Erro ao buscar regras:\', err);\n  }\n}\n\nfunction populateContasSelects() {\n  const selects = [\n    document.getElementById(\'filtro-conta\'),\n    document.getElementById(\'lancamento-conta\'),\n    document.getElementById(\'lancamento-conta-destino\'),\n    document.getElementById(\'transf-origem\'),\n    document.getElementById(\'transf-destino\'),\n    document.getElementById(\'rec-conta\'),\n    document.getElementById(\'import-conta-id\')\n  ];\n\n  selects.forEach(select => {\n    if (!select) return;\n    const isFilter = select.id === \'filtro-conta\';\n    const isOptional = select.id === \'rec-conta\';\n    const isImport = select.id === \'import-conta-id\';\n    \n    let html = isFilter ? \'<option value="">Todas as Contas</option>\' : (isOptional ? \'<option value="">Sem conta padrão</option>\' : \'\');\n    \n    if (state.contas.length === 0) {\n      html += \'<option value="">(Nenhuma conta cadastrada)</option>\';\n    }\n\n    state.contas.forEach(c => {\n      html += `<option value="${c.id}">${c.nome} (${formatBRL(c.saldo_atual)})</option>`;\n    });\n\n    select.innerHTML = html;\n  });\n}\n\nfunction populateCategoriasSelects() {\n  const filterSelect = document.getElementById(\'filtro-categoria\');\n  const recSelect = document.getElementById(\'rec-categoria\');\n\n  if (filterSelect) {\n    let html = \'<option value="">Todas as Categorias</option>\';\n    state.categorias.forEach(cat => {\n      html += `<option value="${cat.id}">${cat.nome} (${cat.tipo})</option>`;\n    });\n    filterSelect.innerHTML = html;\n  }\n\n  updateLancamentoCategorias();\n  \n  if (recSelect) {\n    let html = \'<option value="">Sem categoria</option>\';\n    const filteredCats = state.categorias.filter(c => c.tipo === state.currentRecTipo);\n    filteredCats.forEach(cat => {\n      html += `<option value="${cat.id}">${cat.nome}</option>`;\n    });\n    recSelect.innerHTML = html;\n  }\n}\n\nfunction updateLancamentoCategorias() {\n  const lancamentoSelect = document.getElementById(\'lancamento-categoria\');\n  if (!lancamentoSelect) return;\n\n  let html = \'<option value="">Sem categoria</option>\';\n  const filteredCats = state.categorias.filter(c => c.tipo === state.currentTipoLancamento);\n  filteredCats.forEach(cat => {\n    html += `<option value="${cat.id}">${cat.nome}</option>`;\n  });\n  lancamentoSelect.innerHTML = html;\n}\n\n// ========================================================\n// DASHBOARD & GRÁFICOS\n// ========================================================\nasync function loadDashboard() {\n  try {\n    const res = await fetch(`/api/dashboard?mes=${state.selectedMonth}&ano=${state.selectedYear}`);\n    if (res.status === 401) { window.location.href = \'/login\'; return; }\n    const data = await res.json();\n\n    document.getElementById(\'card-saldo-total\').textContent = formatBRL(data.saldo_consolidado_geral);\n    document.getElementById(\'card-receitas-total\').textContent = formatBRL(data.total_receitas);\n    document.getElementById(\'card-receitas-pagas\').textContent = formatBRL(data.receitas_pagas);\n    document.getElementById(\'card-receitas-pendentes\').textContent = formatBRL(data.receitas_pendentes);\n\n    document.getElementById(\'card-despesas-total\').textContent = formatBRL(data.total_despesas);\n    document.getElementById(\'card-despesas-pagas\').textContent = formatBRL(data.despesas_pagas);\n    document.getElementById(\'card-despesas-pendentes\').textContent = formatBRL(data.despesas_pendentes);\n\n    document.getElementById(\'card-saldo-previsto\').textContent = formatBRL(data.saldo_previsto_mes);\n    \n    const balancoEl = document.getElementById(\'card-balanco-mes\');\n    const sinal = data.balanco_mes >= 0 ? \'+\' : \'\';\n    balancoEl.innerHTML = `Balanço mensal: <b class="${data.balanco_mes >= 0 ? \'text-emerald-500\' : \'text-rose-500\'}">${sinal}${formatBRL(data.balanco_mes)}</b>`;\n\n    renderContasDashboard(data.contas);\n    renderChartCategorias(data.despesas_por_categoria);\n    renderChartHistorico(data.historico_meses);\n    renderAlertas(data.alertas);\n\n    lucide.createIcons();\n  } catch (err) {\n    console.error(\'Erro ao carregar dashboard:\', err);\n  }\n}\n\nfunction renderContasDashboard(contas) {\n  const container = document.getElementById(\'grid-contas-dashboard\');\n  if (!container) return;\n\n  if (contas.length === 0) {\n    container.innerHTML = `\n      <div class="col-span-full p-8 text-center bg-white dark:bg-slate-900/90 rounded-2xl border border-dashed border-slate-200 dark:border-slate-800">\n        <div class="w-10 h-10 rounded-full bg-indigo-50 dark:bg-indigo-950/60 text-indigo-500 flex items-center justify-center mx-auto mb-2.5">\n          <i data-lucide="credit-card" class="w-5 h-5"></i>\n        </div>\n        <p class="text-xs font-semibold text-slate-700 dark:text-slate-300">Nenhuma conta cadastrada ainda</p>\n        <p class="text-[11px] text-slate-400 mt-0.5">Adicione sua conta corrente, carteira ou cartão para começar a controlar.</p>\n        <button onclick="document.getElementById(\'btn-quick-new-account\').click()" class="mt-3 inline-flex items-center gap-1.5 px-3 py-1.5 rounded-xl bg-indigo-600 hover:bg-indigo-700 text-white text-xs font-bold shadow-md shadow-indigo-600/20 transition">\n          <i data-lucide="plus" class="w-3.5 h-3.5"></i>\n          Cadastrar Primeira Conta\n        </button>\n      </div>\n    `;\n    return;\n  }\n\n  container.innerHTML = contas.map(c => `\n    <div class="bank-card bg-white dark:bg-slate-900/90 p-4 rounded-2xl border border-slate-200/80 dark:border-slate-800 shadow-sm flex flex-col justify-between" style="--account-color: ${c.cor};">\n      <div class="flex items-center justify-between mb-3">\n        <div class="flex items-center gap-2.5 min-w-0">\n          <div class="w-9 h-9 rounded-xl flex items-center justify-center text-white shrink-0 shadow-sm" style="background-color: ${c.cor};">\n            <i data-lucide="${c.tipo === \'Carteira\' ? \'wallet\' : (c.tipo === \'Investimento\' ? \'trending-up\' : \'credit-card\')}" class="w-4 h-4"></i>\n          </div>\n          <div class="min-w-0">\n            <h4 class="text-xs font-bold text-slate-900 dark:text-white truncate max-w-[130px]" title="${c.nome}">${c.nome}</h4>\n            <span class="text-[10px] text-slate-400 font-medium truncate block">${c.instituicao || c.tipo}</span>\n          </div>\n        </div>\n        <span class="text-[10px] px-2 py-0.5 rounded-md bg-slate-100 dark:bg-slate-800/80 text-slate-600 dark:text-slate-300 font-semibold border border-slate-200/60 dark:border-slate-700/60 shrink-0">${c.tipo}</span>\n      </div>\n\n      <div class="pt-2.5 border-t border-slate-100 dark:border-slate-800/60 flex items-end justify-between">\n        <div>\n          <span class="text-[10px] uppercase font-semibold text-slate-400 dark:text-slate-500">Saldo Atual</span>\n          <div class="text-base font-black ${c.saldo_atual >= 0 ? \'text-slate-900 dark:text-white\' : \'text-rose-500\'}">\n            ${formatBRL(c.saldo_atual)}\n          </div>\n        </div>\n        <span class="text-[10px] text-indigo-600 dark:text-indigo-400 font-medium">Ativa</span>\n      </div>\n    </div>\n  `).join(\'\');\n}\n\nfunction renderChartCategorias(despesasPorCategoria) {\n  const ctx = document.getElementById(\'chart-categorias\');\n  const emptyMsg = document.getElementById(\'chart-empty-msg\');\n  if (!ctx) return;\n\n  if (state.charts.categorias) {\n    state.charts.categorias.destroy();\n  }\n\n  if (!despesasPorCategoria || despesasPorCategoria.length === 0) {\n    ctx.style.display = \'none\';\n    if (emptyMsg) emptyMsg.classList.remove(\'hidden\');\n    return;\n  }\n\n  ctx.style.display = \'block\';\n  if (emptyMsg) emptyMsg.classList.add(\'hidden\');\n\n  const isDark = document.documentElement.classList.contains(\'dark\');\n  const labels = despesasPorCategoria.map(d => d.categoria);\n  const dataValues = despesasPorCategoria.map(d => d.total);\n  const bgColors = despesasPorCategoria.map(d => d.cor || \'#6366f1\');\n\n  state.charts.categorias = new Chart(ctx, {\n    type: \'doughnut\',\n    data: {\n      labels: labels,\n      datasets: [{\n        data: dataValues,\n        backgroundColor: bgColors,\n        borderWidth: 2,\n        borderColor: isDark ? \'#0f172a\' : \'#ffffff\',\n        hoverOffset: 4\n      }]\n    },\n    options: {\n      responsive: true,\n      maintainAspectRatio: false,\n      plugins: {\n        legend: {\n          position: \'bottom\',\n          labels: {\n            color: isDark ? \'#cbd5e1\' : \'#475569\',\n            font: { size: 11, family: \'Inter\', weight: 500 },\n            boxWidth: 10,\n            padding: 10,\n            usePointStyle: true,\n            pointStyle: \'circle\'\n          }\n        },\n        tooltip: {\n          backgroundColor: isDark ? \'#1e293b\' : \'#ffffff\',\n          titleColor: isDark ? \'#f8fafc\' : \'#0f172a\',\n          bodyColor: isDark ? \'#cbd5e1\' : \'#475569\',\n          borderColor: isDark ? \'#334155\' : \'#e2e8f0\',\n          borderWidth: 1,\n          padding: 10,\n          boxPadding: 4,\n          callbacks: {\n            label: function(context) {\n              const label = context.label || \'\';\n              const value = formatBRL(context.raw);\n              return ` ${label}: ${value}`;\n            }\n          }\n        }\n      },\n      cutout: \'72%\'\n    }\n  });\n}\n\nfunction renderChartHistorico(historico) {\n  const ctx = document.getElementById(\'chart-historico\');\n  if (!ctx) return;\n\n  if (state.charts.historico) {\n    state.charts.historico.destroy();\n  }\n\n  const isDark = document.documentElement.classList.contains(\'dark\');\n  const labels = historico.map(h => h.label);\n  const receitas = historico.map(h => h.receitas);\n  const despesas = historico.map(h => h.despesas);\n\n  state.charts.historico = new Chart(ctx, {\n    type: \'bar\',\n    data: {\n      labels: labels,\n      datasets: [\n        {\n          label: \'Receitas\',\n          data: receitas,\n          backgroundColor: \'#10b981\',\n          borderRadius: 6,\n          barPercentage: 0.55\n        },\n        {\n          label: \'Despesas\',\n          data: despesas,\n          backgroundColor: \'#f43f5e\',\n          borderRadius: 6,\n          barPercentage: 0.55\n        }\n      ]\n    },\n    options: {\n      responsive: true,\n      maintainAspectRatio: false,\n      plugins: {\n        legend: {\n          position: \'top\',\n          align: \'end\',\n          labels: {\n            color: isDark ? \'#cbd5e1\' : \'#475569\',\n            font: { size: 11, family: \'Inter\', weight: 500 },\n            boxWidth: 10,\n            usePointStyle: true,\n            pointStyle: \'circle\'\n          }\n        },\n        tooltip: {\n          backgroundColor: isDark ? \'#1e293b\' : \'#ffffff\',\n          titleColor: isDark ? \'#f8fafc\' : \'#0f172a\',\n          bodyColor: isDark ? \'#cbd5e1\' : \'#475569\',\n          borderColor: isDark ? \'#334155\' : \'#e2e8f0\',\n          borderWidth: 1,\n          padding: 10,\n          callbacks: {\n            label: function(context) {\n              return ` ${context.dataset.label}: ${formatBRL(context.raw)}`;\n            }\n          }\n        }\n      },\n      scales: {\n        x: {\n          grid: { display: false },\n          ticks: { color: isDark ? \'#94a3b8\' : \'#64748b\', font: { size: 10, family: \'Inter\' } }\n        },\n        y: {\n          grid: { color: isDark ? \'rgba(255,255,255,0.06)\' : \'rgba(0,0,0,0.05)\' },\n          ticks: {\n            color: isDark ? \'#94a3b8\' : \'#64748b\',\n            font: { size: 10, family: \'Inter\' },\n            callback: function(value) { return \'R$ \' + value.toLocaleString(\'pt-BR\'); }\n          }\n        }\n      }\n    }\n  });\n}\n\nfunction renderAlertas(alertas) {\n  const container = document.getElementById(\'lista-alertas-dashboard\');\n  const badgeCount = document.getElementById(\'badge-alertas-count\');\n  if (!container) return;\n\n  if (badgeCount) {\n    badgeCount.textContent = alertas.length;\n    if (alertas.length > 0) {\n      badgeCount.className = "text-xs px-2 py-0.5 rounded-full bg-amber-100 dark:bg-amber-900/60 text-amber-700 dark:text-amber-300 font-bold";\n    } else {\n      badgeCount.className = "text-xs px-2 py-0.5 rounded-full bg-slate-100 dark:bg-slate-800 text-slate-500 font-medium";\n    }\n  }\n\n  if (alertas.length === 0) {\n    container.innerHTML = `\n      <div class="h-full flex flex-col items-center justify-center text-center p-6 text-slate-400">\n        <div class="w-10 h-10 rounded-full bg-emerald-50 dark:bg-emerald-950/60 text-emerald-500 flex items-center justify-center mb-2">\n          <i data-lucide="check-circle-2" class="w-5 h-5"></i>\n        </div>\n        <p class="text-xs font-bold text-slate-700 dark:text-slate-300">Tudo em dia!</p>\n        <p class="text-[11px] text-slate-400 mt-0.5">Nenhuma conta com vencimento pendente para os próximos 7 dias.</p>\n      </div>\n    `;\n    return;\n  }\n\n  const hoje = new Date().toISOString().split(\'T\')[0];\n\n  container.innerHTML = alertas.map(a => {\n    const isVencida = a.data < hoje;\n    const isHoje = a.data === hoje;\n    \n    let statusLabel = `Vence em ${formatDateBR(a.data)}`;\n    let badgeClass = "bg-amber-50 dark:bg-amber-950/50 text-amber-700 dark:text-amber-300 border border-amber-200/60 dark:border-amber-800/40";\n    \n    if (isVencida) {\n      statusLabel = `Venceu em ${formatDateBR(a.data)}`;\n      badgeClass = "bg-rose-50 dark:bg-rose-950/50 text-rose-700 dark:text-rose-300 border border-rose-200/60 dark:border-rose-800/40 font-bold";\n    } else if (isHoje) {\n      statusLabel = "Vence Hoje!";\n      badgeClass = "bg-amber-100 dark:bg-amber-900/60 text-amber-800 dark:text-amber-200 border border-amber-300 dark:border-amber-700 font-bold";\n    }\n\n    return `\n      <div class="flex items-center justify-between p-3 rounded-xl bg-slate-50/70 dark:bg-slate-800/50 border border-slate-100 dark:border-slate-800/80 hover:border-slate-300 dark:hover:border-slate-700 transition">\n        <div class="flex items-center gap-3 min-w-0">\n          <div class="w-2 h-2 rounded-full ${isVencida ? \'bg-rose-500 animate-pulse\' : (isHoje ? \'bg-amber-500\' : \'bg-amber-400\')} shrink-0"></div>\n          <div class="min-w-0">\n            <h4 class="text-xs font-bold text-slate-800 dark:text-slate-200 truncate" title="${a.descricao}">${a.descricao}</h4>\n            <div class="flex items-center gap-2 mt-0.5">\n              <span class="text-[10px] px-1.5 py-0.2 rounded-md ${badgeClass}">${statusLabel}</span>\n              <span class="text-[10px] text-slate-400 truncate">${a.conta_nome || \'Sem conta\'}</span>\n            </div>\n          </div>\n        </div>\n        \n        <div class="text-right flex items-center gap-2.5 shrink-0 pl-2">\n          <span class="text-xs font-black text-rose-600 dark:text-rose-400">${formatBRL(a.valor)}</span>\n          <button onclick="toggleTransacaoStatus(${a.id})" title="Marcar como Pago" class="p-1.5 rounded-lg bg-emerald-50 hover:bg-emerald-100 dark:bg-emerald-950/60 dark:hover:bg-emerald-900/60 text-emerald-600 dark:text-emerald-300 border border-emerald-200/60 dark:border-emerald-800/40 transition shadow-sm">\n            <i data-lucide="check" class="w-3.5 h-3.5"></i>\n          </button>\n        </div>\n      </div>\n    `;\n  }).join(\'\');\n}\n\n// ========================================================\n// TRANSAÇÕES / EXTRATO\n// ========================================================\nasync function loadTransacoes() {\n  const busca = document.getElementById(\'filtro-busca\')?.value || \'\';\n  const contaId = document.getElementById(\'filtro-conta\')?.value || \'\';\n  const categoriaId = document.getElementById(\'filtro-categoria\')?.value || \'\';\n  const tipo = document.getElementById(\'filtro-tipo\')?.value || \'\';\n  const status = document.getElementById(\'filtro-status\')?.value || \'\';\n\n  const params = new URLSearchParams({\n    mes: state.selectedMonth,\n    ano: state.selectedYear,\n    q: busca,\n    conta_id: contaId,\n    categoria_id: categoriaId,\n    tipo: tipo,\n    status: status\n  });\n\n  try {\n    const res = await fetch(`/api/transacoes?${params.toString()}`);\n    if (res.status === 401) { window.location.href = \'/login\'; return; }\n    state.transacoes = await res.json();\n    renderTransacoesTable();\n  } catch (err) {\n    console.error(\'Erro ao buscar transações:\', err);\n  }\n}\n\nfunction renderTransacoesTable() {\n  const tbody = document.getElementById(\'tbody-transacoes\');\n  const emptyMsg = document.getElementById(\'transacoes-empty-msg\');\n  const lblTotalReg = document.getElementById(\'lbl-total-registros\');\n  const lblTotalVal = document.getElementById(\'lbl-total-valor-filtrado\');\n\n  if (!tbody) return;\n\n  if (state.transacoes.length === 0) {\n    tbody.innerHTML = \'\';\n    if (emptyMsg) emptyMsg.classList.remove(\'hidden\');\n    if (lblTotalReg) lblTotalReg.textContent = \'0\';\n    if (lblTotalVal) lblTotalVal.textContent = \'R$ 0,00\';\n    return;\n  }\n\n  if (emptyMsg) emptyMsg.classList.add(\'hidden\');\n\n  let totalFiltrado = 0;\n  state.transacoes.forEach(t => {\n    if (t.tipo === \'receita\') totalFiltrado += t.valor;\n    else if (t.tipo === \'despesa\') totalFiltrado -= t.valor;\n  });\n\n  if (lblTotalReg) lblTotalReg.textContent = state.transacoes.length;\n  if (lblTotalVal) {\n    const sinal = totalFiltrado >= 0 ? \'+\' : \'\';\n    lblTotalVal.textContent = `${sinal}${formatBRL(totalFiltrado)}`;\n    lblTotalVal.className = totalFiltrado >= 0 ? \'text-emerald-500 font-bold\' : \'text-rose-500 font-bold\';\n  }\n\n  tbody.innerHTML = state.transacoes.map(t => {\n    const isReceita = t.tipo === \'receita\';\n    const isDespesa = t.tipo === \'despesa\';\n    const isTransf = t.tipo === \'transferencia\';\n    const isPago = t.status === \'pago\';\n\n    let valorColorClass = isReceita ? \'text-emerald-600 dark:text-emerald-400\' : (isDespesa ? \'text-rose-600 dark:text-rose-400\' : \'text-indigo-600 dark:text-indigo-400\');\n    let prefixoValor = isReceita ? \'+ \' : (isDespesa ? \'- \' : \'⇄ \');\n\n    let iconeCategoria = t.categoria_icone || (isReceita ? \'trending-up\' : (isTransf ? \'arrow-left-right\' : \'shopping-bag\'));\n    let corCategoria = t.categoria_cor || (isReceita ? \'#10b981\' : (isTransf ? \'#6366f1\' : \'#f43f5e\'));\n\n    return `\n      <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/40 transition">\n        <td class="py-3 px-4 whitespace-nowrap text-slate-500 dark:text-slate-400 font-mono text-xs">\n          ${formatDateBR(t.data)}\n        </td>\n        <td class="py-3 px-4">\n          <div class="flex items-center gap-3">\n            <div class="w-8 h-8 rounded-xl flex items-center justify-center text-white shrink-0 shadow-sm" style="background-color: ${corCategoria};">\n              <i data-lucide="${iconeCategoria}" class="w-4 h-4"></i>\n            </div>\n            <div>\n              <div class="font-semibold text-slate-900 dark:text-white">${t.descricao}</div>\n              <div class="flex items-center gap-2 text-xs text-slate-500 dark:text-slate-400 mt-0.5">\n                <span>${t.categoria_nome || (isTransf ? \'Transferência\' : \'Geral\')}</span>\n                ${t.observacoes ? `<span>&bull;</span> <span class="italic truncate max-w-[180px]">${t.observacoes}</span>` : \'\'}\n              </div>\n            </div>\n          </div>\n        </td>\n        <td class="py-3 px-4 whitespace-nowrap">\n          ${isTransf ? `\n            <div class="flex items-center gap-1.5 text-xs text-slate-700 dark:text-slate-300">\n              <span class="font-medium">${t.conta_nome}</span>\n              <i data-lucide="arrow-right" class="w-3 h-3 text-slate-400"></i>\n              <span class="font-medium">${t.conta_destino_nome}</span>\n            </div>\n          ` : `\n            <div class="flex items-center gap-2">\n              <span class="w-2.5 h-2.5 rounded-full" style="background-color: ${t.conta_cor || \'#3b82f6\'};"></span>\n              <span class="text-xs font-medium text-slate-800 dark:text-slate-200">${t.conta_nome || \'Sem conta\'}</span>\n            </div>\n          `}\n        </td>\n        <td class="py-3 px-4 text-right whitespace-nowrap font-bold text-sm ${valorColorClass}">\n          ${prefixoValor}${formatBRL(t.valor)}\n        </td>\n        <td class="py-3 px-4 text-center whitespace-nowrap">\n          <button onclick="toggleTransacaoStatus(${t.id})" title="Clique para alternar Pago / Pendente" class="status-pill cursor-pointer hover:opacity-80 ${isPago ? \'status-pago\' : \'status-pendente\'}">\n            <i data-lucide="${isPago ? \'check-circle-2\' : \'clock\'}" class="w-3.5 h-3.5"></i>\n            <span>${isPago ? \'Pago\' : \'Pendente\'}</span>\n          </button>\n        </td>\n        <td class="py-3 px-4 text-center whitespace-nowrap">\n          <div class="flex items-center justify-center gap-1.5">\n            <button onclick="editarTransacao(${t.id})" title="Editar Lançamento" class="p-1.5 text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition">\n              <i data-lucide="pencil" class="w-3.5 h-3.5"></i>\n            </button>\n            <button onclick="excluirTransacao(${t.id})" title="Excluir" class="p-1.5 text-slate-400 hover:text-rose-600 dark:hover:text-rose-400 hover:bg-slate-100 dark:hover:bg-slate-800 rounded-lg transition">\n              <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>\n            </button>\n          </div>\n        </td>\n      </tr>\n    `;\n  }).join(\'\');\n\n  lucide.createIcons();\n}\n\nasync function toggleTransacaoStatus(id) {\n  try {\n    const res = await fetch(`/api/transacoes/${id}/status`, { method: \'PATCH\' });\n    const data = await res.json();\n    if (data.success) {\n      await loadAllData();\n      const Toast = Swal.mixin({\n        toast: true, position: \'top-end\', showConfirmButton: false, timer: 1800, timerProgressBar: true\n      });\n      Toast.fire({ icon: \'success\', title: data.message });\n    }\n  } catch (err) {\n    console.error(\'Erro ao alternar status:\', err);\n  }\n}\n\nasync function excluirTransacao(id) {\n  const result = await Swal.fire({\n    title: \'Excluir Lançamento?\',\n    text: \'Esta ação não pode ser desfeita e atualizará o saldo da conta.\',\n    icon: \'warning\',\n    showCancelButton: true,\n    confirmButtonColor: \'#ef4444\',\n    cancelButtonColor: \'#64748b\',\n    confirmButtonText: \'Sim, excluir\',\n    cancelButtonText: \'Cancelar\'\n  });\n\n  if (result.isConfirmed) {\n    try {\n      const res = await fetch(`/api/transacoes/${id}`, { method: \'DELETE\' });\n      const data = await res.json();\n      if (data.success) {\n        await loadAllData();\n        Swal.fire({ title: \'Excluído!\', text: \'O lançamento foi removido com sucesso.\', icon: \'success\', timer: 1200, showConfirmButton: false });\n      }\n    } catch (err) {\n      console.error(\'Erro ao excluir transação:\', err);\n    }\n  }\n}\n\nasync function zerarLancamentosMesAtual() {\n  const mesNome = nomesMeses[state.selectedMonth];\n  const ano = state.selectedYear;\n\n  const result = await Swal.fire({\n    title: `Zerar ${mesNome}/${ano}?`,\n    html: `\n      <p class="text-sm text-slate-400">Você tem certeza que deseja <b>apagar todos os lançamentos</b> de <b>${mesNome}/${ano}</b>?</p>\n      <p class="text-xs text-rose-400 mt-2 font-semibold">Os saldos das suas contas serão recalculados imediatamente.</p>\n    `,\n    icon: \'warning\',\n    showCancelButton: true,\n    confirmButtonColor: \'#ef4444\',\n    cancelButtonColor: \'#64748b\',\n    confirmButtonText: \'Sim, zerar tudo deste mês\',\n    cancelButtonText: \'Cancelar\'\n  });\n\n  if (result.isConfirmed) {\n    try {\n      const res = await fetch(\'/api/transacoes/zerar-mes\', {\n        method: \'POST\',\n        headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify({ mes: state.selectedMonth, ano: state.selectedYear })\n      });\n      const data = await res.json();\n      if (data.success) {\n        await loadAllData();\n        Swal.fire({\n          icon: \'success\',\n          title: \'Mês Zerado!\',\n          text: data.message,\n          timer: 1800,\n          showConfirmButton: false\n        });\n      }\n    } catch (err) {\n      console.error(\'Erro ao zerar mês:\', err);\n    }\n  }\n}\n\nfunction editarTransacao(id) {\n  const trans = state.transacoes.find(t => t.id === id);\n  if (!trans) return;\n\n  document.getElementById(\'modal-lancamento-titulo\').textContent = \'Editar Lançamento\';\n  document.getElementById(\'lancamento-id\').value = trans.id;\n  document.getElementById(\'lancamento-descricao\').value = trans.descricao;\n  document.getElementById(\'lancamento-valor\').value = trans.valor;\n  document.getElementById(\'lancamento-data\').value = trans.data;\n  document.getElementById(\'lancamento-status\').value = trans.status;\n  document.getElementById(\'lancamento-observacoes\').value = trans.observacoes || \'\';\n\n  setTipoLancamento(trans.tipo);\n\n  if (trans.conta_id) {\n    document.getElementById(\'lancamento-conta\').value = trans.conta_id;\n  }\n  if (trans.conta_destino_id) {\n    document.getElementById(\'lancamento-conta-destino\').value = trans.conta_destino_id;\n  }\n  if (trans.categoria_id) {\n    document.getElementById(\'lancamento-categoria\').value = trans.categoria_id;\n  }\n\n  openModal(\'modal-lancamento\');\n}\n\n// ========================================================\n// IMPORTAÇÃO BANCÁRIA INTELIGENTE (OFX, CSV, TXT)\n// ========================================================\nfunction setupImportEventListeners() {\n  const dropzone = document.getElementById(\'import-dropzone\');\n  const fileInput = document.getElementById(\'import-file-input\');\n  const btnProcess = document.getElementById(\'btn-import-process-file\');\n  const btnVoltar = document.getElementById(\'btn-import-voltar\');\n  const btnConfirmFinal = document.getElementById(\'btn-import-confirmar-final\');\n  const btnSelectAll = document.getElementById(\'btn-import-select-all\');\n  const btnUnselectAll = document.getElementById(\'btn-import-unselect-all\');\n\n  // Abrir modal de importação\n  [\'btn-open-modal-import\', \'btn-quick-import\', \'btn-extrato-importar\'].forEach(id => {\n    document.getElementById(id)?.addEventListener(\'click\', () => {\n      if (state.contas.length === 0) {\n        Swal.fire({\n          icon: \'info\',\n          title: \'Cadastre uma Conta Primeiro\',\n          text: \'Você precisa ter pelo menos uma conta bancária cadastrada para onde importar o extrato.\',\n          confirmButtonColor: \'#4f46e5\'\n        }).then(() => {\n          document.getElementById(\'btn-quick-new-account\')?.click();\n        });\n        return;\n      }\n      resetImportModal();\n      openModal(\'modal-import\');\n    });\n  });\n\n  // Dropzone click & drag\n  if (dropzone && fileInput) {\n    dropzone.addEventListener(\'click\', () => fileInput.click());\n\n    dropzone.addEventListener(\'dragover\', (e) => {\n      e.preventDefault();\n      dropzone.classList.add(\'border-indigo-500\', \'bg-indigo-50/50\', \'dark:bg-indigo-950/40\');\n    });\n\n    [\'dragleave\', \'drop\'].forEach(evt => {\n      dropzone.addEventListener(evt, (e) => {\n        e.preventDefault();\n        dropzone.classList.remove(\'border-indigo-500\', \'bg-indigo-50/50\', \'dark:bg-indigo-950/40\');\n      });\n    });\n\n    dropzone.addEventListener(\'drop\', (e) => {\n      if (e.dataTransfer.files && e.dataTransfer.files[0]) {\n        handleFileSelected(e.dataTransfer.files[0]);\n      }\n    });\n\n    fileInput.addEventListener(\'change\', (e) => {\n      if (e.target.files && e.target.files[0]) {\n        handleFileSelected(e.target.files[0]);\n      }\n    });\n  }\n\n  // Processar e Gerar Prévia\n  btnProcess?.addEventListener(\'click\', processImportFilePreview);\n\n  // Voltar para Etapa 1\n  btnVoltar?.addEventListener(\'click\', () => {\n    document.getElementById(\'import-etapa-2\')?.classList.add(\'hidden\');\n    document.getElementById(\'import-etapa-1\')?.classList.remove(\'hidden\');\n  });\n\n  // Selecionar / Desmarcar Todos\n  btnSelectAll?.addEventListener(\'click\', () => toggleAllImportSelection(true));\n  btnUnselectAll?.addEventListener(\'click\', () => toggleAllImportSelection(false));\n\n  // Confirmar Importação Final\n  btnConfirmFinal?.addEventListener(\'click\', confirmImportTransactions);\n}\n\nfunction resetImportModal() {\n  state.import.selectedFile = null;\n  state.import.previewTransactions = [];\n  const fileInput = document.getElementById(\'import-file-input\');\n  if (fileInput) fileInput.value = \'\';\n\n  document.getElementById(\'import-selected-file-info\')?.classList.add(\'hidden\');\n  document.getElementById(\'import-etapa-1\')?.classList.remove(\'hidden\');\n  document.getElementById(\'import-etapa-2\')?.classList.add(\'hidden\');\n}\n\nfunction handleFileSelected(file) {\n  state.import.selectedFile = file;\n  const infoContainer = document.getElementById(\'import-selected-file-info\');\n  const nameEl = document.getElementById(\'import-file-name\');\n  const sizeEl = document.getElementById(\'import-file-size\');\n\n  if (infoContainer && nameEl && sizeEl) {\n    nameEl.textContent = file.name;\n    sizeEl.textContent = (file.size / 1024).toFixed(1) + \' KB\';\n    infoContainer.classList.remove(\'hidden\');\n  }\n}\n\nasync function processImportFilePreview() {\n  if (!state.import.selectedFile) {\n    Swal.fire({ icon: \'warning\', title: \'Atenção\', text: \'Selecione um arquivo de extrato bancário.\' });\n    return;\n  }\n\n  const contaId = document.getElementById(\'import-conta-id\')?.value;\n  if (!contaId) {\n    Swal.fire({ icon: \'warning\', title: \'Atenção\', text: \'Selecione a conta bancária de destino.\' });\n    return;\n  }\n\n  state.import.contaId = contaId;\n\n  const formData = new FormData();\n  formData.append(\'arquivo\', state.import.selectedFile);\n  formData.append(\'conta_id\', contaId);\n\n  // Exibir loading\n  Swal.fire({\n    title: \'Analisando Extrato...\',\n    text: \'Identificando movimentações e aplicando Auto-Categorização com IA.\',\n    allowOutsideClick: false,\n    didOpen: () => {\n      Swal.showLoading();\n    }\n  });\n\n  try {\n    const res = await fetch(\'/api/import/preview\', {\n      method: \'POST\',\n      body: formData\n    });\n\n    const data = await res.json();\n    Swal.close();\n\n    if (!res.ok || !data.success) {\n      Swal.fire({ icon: \'error\', title: \'Erro ao processar extrato\', text: data.error || \'Verifique o formato do arquivo.\' });\n      return;\n    }\n\n    state.import.previewTransactions = data.transacoes;\n    renderImportPreviewTable(data);\n\n    // Mudar para etapa 2\n    document.getElementById(\'import-etapa-1\')?.classList.add(\'hidden\');\n    document.getElementById(\'import-etapa-2\')?.classList.remove(\'hidden\');\n  } catch (err) {\n    Swal.close();\n    console.error(\'Erro na requisição de preview:\', err);\n    Swal.fire({ icon: \'error\', title: \'Erro de conexão\', text: \'Não foi possível enviar o arquivo para análise.\' });\n  }\n}\n\nfunction renderImportPreviewTable(previewData) {\n  const tbody = document.getElementById(\'tbody-import-preview\');\n  const statsEl = document.getElementById(\'import-preview-stats\');\n  const recEl = document.getElementById(\'import-preview-rec\');\n  const despEl = document.getElementById(\'import-preview-desp\');\n  const btnConfirmLbl = document.getElementById(\'lbl-btn-confirm-import\');\n\n  if (statsEl) statsEl.textContent = `${previewData.total_transacoes} lançamentos encontrados`;\n  if (recEl) recEl.textContent = `+${formatBRL(previewData.total_receitas)}`;\n  if (despEl) despEl.textContent = `-${formatBRL(previewData.total_despesas)}`;\n\n  if (!tbody) return;\n\n  tbody.innerHTML = previewData.transacoes.map((t, idx) => {\n    const isReceita = t.tipo === \'receita\';\n    const valorColor = isReceita ? \'text-emerald-600 dark:text-emerald-400\' : \'text-rose-600 dark:text-rose-400\';\n    const valorPrefix = isReceita ? \'+\' : \'-\';\n\n    // Opções de categorias filtradas por tipo\n    const catsForType = state.categorias.filter(c => c.tipo === t.tipo);\n    const catOptionsHtml = catsForType.map(c => `\n      <option value="${c.id}" ${c.id === t.categoria_id ? \'selected\' : \'\'}>${c.nome}</option>\n    `).join(\'\');\n\n    // Badge de origem da sugestão\n    let badgeOrigem = \'\';\n    if (t.origem_sugestao === \'regra_aprendida\') {\n      badgeOrigem = \'<span class="inline-flex items-center gap-1 text-[10px] px-1.5 py-0.2 rounded bg-indigo-100 dark:bg-indigo-900/60 text-indigo-700 dark:text-indigo-300 font-bold">🧠 Regra</span>\';\n    } else if (t.origem_sugestao === \'historico\') {\n      badgeOrigem = \'<span class="inline-flex items-center gap-1 text-[10px] px-1.5 py-0.2 rounded bg-blue-100 dark:bg-blue-900/60 text-blue-700 dark:text-blue-300 font-bold">🕒 Histórico</span>\';\n    } else if (t.origem_sugestao === \'semantica\') {\n      badgeOrigem = \'<span class="inline-flex items-center gap-1 text-[10px] px-1.5 py-0.2 rounded bg-purple-100 dark:bg-purple-900/60 text-purple-700 dark:text-purple-300 font-bold">✨ IA Sugerido</span>\';\n    }\n\n    return `\n      <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/40 transition ${t.is_duplicada ? \'bg-amber-50/40 dark:bg-amber-950/20\' : \'\'}" data-row-id="${t.temp_id}">\n        \n        <!-- Checkbox de Seleção -->\n        <td class="py-2.5 px-3 text-center">\n          <input type="checkbox" class="import-row-checkbox w-4 h-4 text-indigo-600 rounded cursor-pointer" \n                 data-id="${t.temp_id}" ${t.selecionada ? \'checked\' : \'\'} onchange="updateImportSelectionState(${t.temp_id}, this.checked)">\n        </td>\n\n        <!-- Data -->\n        <td class="py-2.5 px-3 whitespace-nowrap font-mono text-slate-500 dark:text-slate-400">\n          ${formatDateBR(t.data)}\n        </td>\n\n        <!-- Descrição -->\n        <td class="py-2.5 px-3">\n          <div class="font-semibold text-slate-900 dark:text-white text-xs">${t.descricao}</div>\n          ${t.is_duplicada ? \'<span class="text-[10px] px-1.5 py-0.2 rounded bg-amber-100 dark:bg-amber-900/40 text-amber-800 dark:text-amber-300 font-semibold">⚠️ Possível duplicata</span>\' : \'\'}\n        </td>\n\n        <!-- Valor -->\n        <td class="py-2.5 px-3 text-right whitespace-nowrap font-bold ${valorColor}">\n          ${valorPrefix}${formatBRL(t.valor)}\n        </td>\n\n        <!-- Seletor de Categoria Interativo -->\n        <td class="py-2.5 px-3">\n          <div class="flex items-center gap-1.5">\n            <select class="import-category-select text-xs px-2.5 py-1 bg-white dark:bg-slate-800 border border-slate-200 dark:border-slate-700 rounded-lg focus:ring-1 focus:ring-indigo-500 dark:text-white"\n                    data-id="${t.temp_id}" onchange="handleCategoryChange(${t.temp_id}, this.value)">\n              <option value="">Sem categoria</option>\n              ${catOptionsHtml}\n            </select>\n            ${badgeOrigem}\n          </div>\n        </td>\n\n        <!-- Checkbox Lembrar Regra -->\n        <td class="py-2.5 px-3 text-center">\n          <label class="inline-flex items-center cursor-pointer" title="Lembrar esta categoria para descrições similares nos próximos extratos">\n            <input type="checkbox" class="import-remember-checkbox w-4 h-4 text-indigo-600 rounded cursor-pointer"\n                   data-id="${t.temp_id}" ${t.origem_sugestao !== \'regra_aprendida\' ? \'checked\' : \'\'}\n                   onchange="updateRememberRuleState(${t.temp_id}, this.checked)">\n          </label>\n        </td>\n\n      </tr>\n    `;\n  }).join(\'\');\n\n  updateImportConfirmButtonLabel();\n  lucide.createIcons();\n}\n\nfunction updateImportSelectionState(tempId, isChecked) {\n  const trans = state.import.previewTransactions.find(t => t.temp_id === tempId);\n  if (trans) trans.selecionada = isChecked;\n  updateImportConfirmButtonLabel();\n}\n\nfunction handleCategoryChange(tempId, newCatId) {\n  const trans = state.import.previewTransactions.find(t => t.temp_id === tempId);\n  if (trans) {\n    trans.categoria_id = newCatId ? parseInt(newCatId) : null;\n    // Marca para memorizar por padrão quando o usuário altera manualmente a categoria\n    trans.lembrar_regra = true;\n    const rememberCheckbox = document.querySelector(`.import-remember-checkbox[data-id="${tempId}"]`);\n    if (rememberCheckbox) rememberCheckbox.checked = true;\n  }\n}\n\nfunction updateRememberRuleState(tempId, isChecked) {\n  const trans = state.import.previewTransactions.find(t => t.temp_id === tempId);\n  if (trans) trans.lembrar_regra = isChecked;\n}\n\nfunction toggleAllImportSelection(selected) {\n  state.import.previewTransactions.forEach(t => t.selecionada = selected);\n  document.querySelectorAll(\'.import-row-checkbox\').forEach(cb => cb.checked = selected);\n  updateImportConfirmButtonLabel();\n}\n\nfunction updateImportConfirmButtonLabel() {\n  const count = state.import.previewTransactions.filter(t => t.selecionada).length;\n  const lbl = document.getElementById(\'lbl-btn-confirm-import\');\n  if (lbl) {\n    lbl.textContent = `Confirmar Importação (${count} selecionadas)`;\n  }\n}\n\nasync function confirmImportTransactions() {\n  const selectedTrans = state.import.previewTransactions.filter(t => t.selecionada);\n\n  if (selectedTrans.length === 0) {\n    Swal.fire({\n      icon: \'warning\',\n      title: \'Nenhum lançamento selecionado\',\n      text: \'Marque pelo menos uma transação na tabela para importar.\'\n    });\n    return;\n  }\n\n  // Prepara payload\n  const payload = {\n    conta_id: state.import.contaId,\n    transacoes: selectedTrans.map(t => {\n      const rememberCb = document.querySelector(`.import-remember-checkbox[data-id="${t.temp_id}"]`);\n      const isLembrar = rememberCb ? rememberCb.checked : (t.lembrar_regra ?? true);\n\n      return {\n        data: t.data,\n        descricao: t.descricao,\n        valor: t.valor,\n        tipo: t.tipo,\n        categoria_id: t.categoria_id,\n        fitid: t.fitid,\n        lembrar_regra: isLembrar,\n        termo_regra: t.termo_regra_sugerido || t.descricao\n      };\n    })\n  };\n\n  Swal.fire({\n    title: \'Gravando Lançamentos...\',\n    text: \'Atualizando seus saldos e memorizando regras aprendidas.\',\n    allowOutsideClick: false,\n    didOpen: () => {\n      Swal.showLoading();\n    }\n  });\n\n  try {\n    const res = await fetch(\'/api/import/confirm\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify(payload)\n    });\n\n    const data = await res.json();\n    Swal.close();\n\n    if (data.success) {\n      closeModal(\'modal-import\');\n      resetImportModal();\n      await loadAllData();\n\n      Swal.fire({\n        icon: \'success\',\n        title: \'Importação Concluída com Sucesso!\',\n        html: `\n          <p class="text-sm text-slate-600 dark:text-slate-300">${data.message}</p>\n        `,\n        confirmButtonColor: \'#4f46e5\'\n      });\n    } else {\n      Swal.fire({ icon: \'error\', title: \'Erro ao gravar transações\', text: data.error });\n    }\n  } catch (err) {\n    Swal.close();\n    console.error(\'Erro na confirmação:\', err);\n    Swal.fire({ icon: \'error\', title: \'Erro de conexão\', text: \'Não foi possível gravar os lançamentos.\' });\n  }\n}\n\n// ========================================================\n// RECORRÊNCIAS & DESPESAS FIXAS\n// ========================================================\nasync function loadRecorrencias() {\n  try {\n    const res = await fetch(\'/api/recorrencias\');\n    if (res.status === 401) { window.location.href = \'/login\'; return; }\n    state.recorrencias = await res.json();\n    renderRecorrenciasTable();\n  } catch (err) {\n    console.error(\'Erro ao carregar recorrências:\', err);\n  }\n}\n\nfunction renderRecorrenciasTable() {\n  const tbody = document.getElementById(\'tbody-recorrencias\');\n  const emptyMsg = document.getElementById(\'recorrencias-empty-msg\');\n  if (!tbody) return;\n\n  if (state.recorrencias.length === 0) {\n    tbody.innerHTML = \'\';\n    if (emptyMsg) emptyMsg.classList.remove(\'hidden\');\n    return;\n  }\n\n  if (emptyMsg) emptyMsg.classList.add(\'hidden\');\n\n  tbody.innerHTML = state.recorrencias.map(r => {\n    const isReceita = r.tipo === \'receita\';\n    return `\n      <tr class="hover:bg-slate-50 dark:hover:bg-slate-800/40 transition">\n        <td class="py-3.5 px-4 font-mono font-bold text-indigo-600 dark:text-indigo-400 whitespace-nowrap">\n          Todo dia ${r.dia_vencimento}\n        </td>\n        <td class="py-3.5 px-4">\n          <div class="flex items-center gap-2.5">\n            <div class="w-8 h-8 rounded-xl flex items-center justify-center text-white" style="background-color: ${r.categoria_cor || (isReceita ? \'#10b981\' : \'#f43f5e\')};">\n              <i data-lucide="${r.categoria_icone || \'refresh-cw\'}" class="w-4 h-4"></i>\n            </div>\n            <div>\n              <span class="font-bold text-slate-900 dark:text-white">${r.descricao}</span>\n              <div class="text-xs text-slate-500">${r.categoria_nome || \'Sem Categoria\'}</div>\n            </div>\n          </div>\n        </td>\n        <td class="py-3.5 px-4 text-xs font-mono text-slate-600 dark:text-slate-400 whitespace-nowrap">\n          ${formatDateBR(r.data_inicio)}\n        </td>\n        <td class="py-3.5 px-4 text-slate-700 dark:text-slate-300 whitespace-nowrap">\n          ${r.conta_nome || \'<span class="text-slate-400">Não definida</span>\'}\n        </td>\n        <td class="py-3.5 px-4 text-right font-extrabold whitespace-nowrap ${isReceita ? \'text-emerald-600 dark:text-emerald-400\' : \'text-rose-600 dark:text-rose-400\'}">\n          ${isReceita ? \'+ \' : \'- \'}${formatBRL(r.valor)}\n        </td>\n        <td class="py-3.5 px-4 text-center whitespace-nowrap">\n          <div class="flex items-center justify-center gap-1.5">\n            <button onclick="editarRecorrencia(${r.id})" title="Editar Recorrência" class="p-1.5 text-slate-400 hover:text-indigo-600 dark:hover:text-indigo-400 rounded-lg transition">\n              <i data-lucide="pencil" class="w-3.5 h-3.5"></i>\n            </button>\n            <button onclick="excluirRecorrenciaDefinitivo(${r.id})" title="Excluir Definitivo (Remove do Dashboard)" class="p-1.5 text-slate-400 hover:text-rose-600 dark:hover:text-rose-400 rounded-lg transition">\n              <i data-lucide="trash-2" class="w-3.5 h-3.5"></i>\n            </button>\n          </div>\n        </td>\n      </tr>\n    `;\n  }).join(\'\');\n\n  lucide.createIcons();\n}\n\nasync function forceGenerateRecurring() {\n  try {\n    const res = await fetch(\'/api/recorrencias/gerar\', {\n      method: \'POST\',\n      headers: { \'Content-Type\': \'application/json\' },\n      body: JSON.stringify({ mes: state.selectedMonth, ano: state.selectedYear })\n    });\n    const data = await res.json();\n    await loadAllData();\n\n    Swal.fire({\n      icon: \'success\',\n      title: \'Recorrências Sincronizadas!\',\n      text: data.message,\n      timer: 2000,\n      showConfirmButton: false\n    });\n  } catch (err) {\n    console.error(\'Erro ao gerar recorrências:\', err);\n  }\n}\n\nfunction editarRecorrencia(id) {\n  const rec = state.recorrencias.find(r => r.id === id);\n  if (!rec) return;\n\n  document.getElementById(\'modal-rec-titulo\').textContent = \'Editar Recorrência\';\n  document.getElementById(\'rec-id\').value = rec.id;\n  document.getElementById(\'rec-descricao\').value = rec.descricao;\n  document.getElementById(\'rec-valor\').value = rec.valor;\n  document.getElementById(\'rec-dia\').value = rec.dia_vencimento;\n  document.getElementById(\'rec-data-inicio\').value = rec.data_inicio || new Date().toISOString().split(\'T\')[0];\n  document.getElementById(\'rec-data-fim\').value = rec.data_fim || \'\';\n\n  setTipoRecorrencia(rec.tipo);\n\n  if (rec.conta_id) {\n    document.getElementById(\'rec-conta\').value = rec.conta_id;\n  }\n  if (rec.categoria_id) {\n    document.getElementById(\'rec-categoria\').value = rec.categoria_id;\n  }\n\n  openModal(\'modal-recorrencia\');\n}\n\nasync function excluirRecorrenciaDefinitivo(id) {\n  const result = await Swal.fire({\n    title: \'Excluir Recorrência?\',\n    html: `\n      <p class="text-sm text-slate-400">A recorrência será removida e <b>todas as despesas pendentes geradas no dashboard serão excluídas imediatamente</b>.</p>\n    `,\n    icon: \'warning\',\n    showCancelButton: true,\n    confirmButtonColor: \'#ef4444\',\n    cancelButtonColor: \'#64748b\',\n    confirmButtonText: \'Sim, excluir definitivo\',\n    cancelButtonText: \'Cancelar\'\n  });\n\n  if (result.isConfirmed) {\n    try {\n      const res = await fetch(`/api/recorrencias/${id}?remover_pendentes=true`, { method: \'DELETE\' });\n      const data = await res.json();\n      if (data.success) {\n        await loadAllData();\n        Swal.fire({\n          title: \'Removida com Sucesso!\',\n          text: data.message,\n          icon: \'success\',\n          timer: 1600,\n          showConfirmButton: false\n        });\n      }\n    } catch (err) {\n      console.error(err);\n    }\n  }\n}\n\n// ========================================================\n// CONTAS BANCÁRIAS (TAB GESTÃO)\n// ========================================================\nfunction renderContasTab() {\n  const container = document.getElementById(\'grid-contas-gerenciamento\');\n  if (!container) return;\n\n  if (state.contas.length === 0) {\n    container.innerHTML = `\n      <div class="col-span-full p-12 text-center bg-white dark:bg-slate-900 rounded-2xl border border-dashed border-slate-200 dark:border-slate-800">\n        <div class="w-12 h-12 rounded-full bg-indigo-50 dark:bg-indigo-950/60 flex items-center justify-center mx-auto mb-3 text-indigo-500">\n          <i data-lucide="landmark" class="w-6 h-6"></i>\n        </div>\n        <p class="text-sm font-bold text-slate-800 dark:text-slate-200">Você ainda não possui contas bancárias cadastradas</p>\n        <p class="text-xs text-slate-500 dark:text-slate-400 mt-1">Cadastre seus bancos ou carteira em dinheiro para gerenciar saldos e transferências.</p>\n        <button onclick="document.getElementById(\'btn-nova-conta-tab\').click()" class="mt-4 px-4 py-2 rounded-xl bg-indigo-600 text-white text-xs font-bold shadow-md shadow-indigo-600/30">\n          + Cadastrar Minha Primeira Conta\n        </button>\n      </div>\n    `;\n    lucide.createIcons();\n    return;\n  }\n\n  container.innerHTML = state.contas.map(c => `\n    <div class="bank-card bg-white dark:bg-slate-900 p-5 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between" style="--account-color: ${c.cor};">\n      <div>\n        <div class="flex items-center justify-between">\n          <div class="flex items-center gap-3">\n            <div class="w-10 h-10 rounded-xl flex items-center justify-center text-white font-bold" style="background-color: ${c.cor};">\n              <i data-lucide="landmark" class="w-5 h-5"></i>\n            </div>\n            <div>\n              <h3 class="font-bold text-slate-900 dark:text-white">${c.nome}</h3>\n              <p class="text-xs text-slate-500 dark:text-slate-400">${c.instituicao || \'\'} &bull; ${c.tipo}</p>\n            </div>\n          </div>\n          <div class="flex items-center gap-1">\n            <button onclick="editarConta(${c.id})" title="Editar Conta" class="p-1.5 text-slate-400 hover:text-indigo-600 rounded-lg">\n              <i data-lucide="pencil" class="w-4 h-4"></i>\n            </button>\n            <button onclick="excluirConta(${c.id})" title="Desativar Conta" class="p-1.5 text-slate-400 hover:text-rose-600 rounded-lg">\n              <i data-lucide="trash-2" class="w-4 h-4"></i>\n            </button>\n          </div>\n        </div>\n\n        <div class="mt-4 pt-4 border-t border-slate-100 dark:border-slate-800/80 space-y-2">\n          <div class="flex justify-between text-xs">\n            <span class="text-slate-500">Saldo Inicial:</span>\n            <span class="font-medium text-slate-700 dark:text-slate-300">${formatBRL(c.saldo_inicial)}</span>\n          </div>\n          <div class="flex justify-between text-xs">\n            <span class="text-slate-500">Receitas Recebidas:</span>\n            <span class="font-medium text-emerald-500">+${formatBRL(c.receitas_pagas || 0)}</span>\n          </div>\n          <div class="flex justify-between text-xs">\n            <span class="text-slate-500">Despesas Pagas:</span>\n            <span class="font-medium text-rose-500">-${formatBRL(c.despesas_pagas || 0)}</span>\n          </div>\n        </div>\n      </div>\n\n      <div class="mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between">\n        <span class="text-xs font-semibold text-slate-500">Saldo Atual:</span>\n        <span class="text-xl font-extrabold ${c.saldo_atual >= 0 ? \'text-slate-900 dark:text-white\' : \'text-rose-500\'}">\n          ${formatBRL(c.saldo_atual)}\n        </span>\n      </div>\n    </div>\n  `).join(\'\');\n\n  lucide.createIcons();\n}\n\nfunction editarConta(id) {\n  const conta = state.contas.find(c => c.id === id);\n  if (!conta) return;\n\n  document.getElementById(\'modal-conta-titulo\').textContent = \'Editar Conta Bancária\';\n  document.getElementById(\'conta-id\').value = conta.id;\n  document.getElementById(\'conta-nome\').value = conta.nome;\n  document.getElementById(\'conta-instituicao\').value = conta.instituicao || \'\';\n  document.getElementById(\'conta-tipo\').value = conta.tipo;\n  document.getElementById(\'conta-saldo-inicial\').value = conta.saldo_inicial;\n  document.getElementById(\'conta-cor\').value = conta.cor || \'#3b82f6\';\n  document.getElementById(\'conta-cor-label\').textContent = conta.cor || \'#3b82f6\';\n\n  openModal(\'modal-conta\');\n}\n\nasync function excluirConta(id) {\n  const result = await Swal.fire({\n    title: \'Desativar Conta Bancária?\',\n    text: \'A conta será arquivada e não aparecerá nos novos lançamentos.\',\n    icon: \'warning\',\n    showCancelButton: true,\n    confirmButtonColor: \'#ef4444\',\n    confirmButtonText: \'Sim, desativar\',\n    cancelButtonText: \'Cancelar\'\n  });\n\n  if (result.isConfirmed) {\n    try {\n      const res = await fetch(`/api/contas/${id}`, { method: \'DELETE\' });\n      const data = await res.json();\n      if (data.success) {\n        await loadAllData();\n        Swal.fire({ title: \'Desativada!\', icon: \'success\', timer: 1200, showConfirmButton: false });\n      } else {\n        Swal.fire({ title: \'Atenção\', text: data.error, icon: \'info\' });\n      }\n    } catch (err) {\n      console.error(err);\n    }\n  }\n}\n\n// ========================================================\n// CATEGORIAS & MEMÓRIA DE REGRAS INTELIGENTES\n// ========================================================\nfunction renderCategoriasTab() {\n  const listaDespesas = document.getElementById(\'lista-categorias-despesa\');\n  const listaReceitas = document.getElementById(\'lista-categorias-receita\');\n\n  const despesas = state.categorias.filter(c => c.tipo === \'despesa\');\n  const receitas = state.categorias.filter(c => c.tipo === \'receita\');\n\n  if (listaDespesas) {\n    listaDespesas.innerHTML = despesas.map(c => `\n      <div class="flex items-center justify-between p-2.5 rounded-xl bg-slate-50 dark:bg-slate-800/60 border border-slate-100 dark:border-slate-800">\n        <div class="flex items-center gap-3">\n          <div class="w-7 h-7 rounded-lg flex items-center justify-center text-white" style="background-color: ${c.cor || \'#64748b\'};">\n            <i data-lucide="${c.icone || \'tag\'}" class="w-3.5 h-3.5"></i>\n          </div>\n          <span class="text-xs font-semibold text-slate-800 dark:text-slate-200">${c.nome}</span>\n        </div>\n      </div>\n    `).join(\'\');\n  }\n\n  if (listaReceitas) {\n    listaReceitas.innerHTML = receitas.map(c => `\n      <div class="flex items-center justify-between p-2.5 rounded-xl bg-slate-50 dark:bg-slate-800/60 border border-slate-100 dark:border-slate-800">\n        <div class="flex items-center gap-3">\n          <div class="w-7 h-7 rounded-lg flex items-center justify-center text-white" style="background-color: ${c.cor || \'#10b981\'};">\n            <i data-lucide="${c.icone || \'trending-up\'}" class="w-3.5 h-3.5"></i>\n          </div>\n          <span class="text-xs font-semibold text-slate-800 dark:text-slate-200">${c.nome}</span>\n        </div>\n      </div>\n    `).join(\'\');\n  }\n\n  renderRegrasAprendidasGrid();\n  lucide.createIcons();\n}\n\nfunction renderRegrasAprendidasGrid() {\n  const container = document.getElementById(\'grid-regras-aprendidas\');\n  const countBadge = document.getElementById(\'badge-regras-count\');\n  if (!container) return;\n\n  if (countBadge) {\n    countBadge.textContent = `${state.regrasAprendidas.length} regras`;\n  }\n\n  if (state.regrasAprendidas.length === 0) {\n    container.innerHTML = `\n      <div class="col-span-full p-6 text-center text-slate-400 bg-slate-50/50 dark:bg-slate-800/40 rounded-xl border border-dashed border-slate-200 dark:border-slate-700/60">\n        <p class="text-xs">Nenhuma regra personalizada memorizada ainda.</p>\n        <p class="text-[11px] text-slate-500 mt-1">Ao importar extratos bancários, marque "Lembrar" para memorizar novos padrões.</p>\n      </div>\n    `;\n    return;\n  }\n\n  container.innerHTML = state.regrasAprendidas.map(r => `\n    <div class="p-2.5 rounded-xl bg-slate-50 dark:bg-slate-800/60 border border-slate-200/80 dark:border-slate-700/60 flex items-center justify-between gap-2">\n      <div class="min-w-0 flex-1">\n        <span class="text-xs font-mono font-bold text-slate-900 dark:text-white uppercase truncate block">${r.termo_busca}</span>\n        <span class="text-[10px] text-indigo-600 dark:text-indigo-400 font-medium truncate block">➜ ${r.categoria_nome}</span>\n      </div>\n      <button onclick="excluirRegraAprendida(${r.id})" title="Remover Regra" class="p-1 text-slate-400 hover:text-rose-500 rounded">\n        <i data-lucide="x" class="w-3.5 h-3.5"></i>\n      </button>\n    </div>\n  `).join(\'\');\n\n  lucide.createIcons();\n}\n\nasync function excluirRegraAprendida(id) {\n  try {\n    const res = await fetch(`/api/regras-categorizacao/${id}`, { method: \'DELETE\' });\n    const data = await res.json();\n    if (data.success) {\n      await fetchRegrasAprendidas();\n    }\n  } catch (err) {\n    console.error(\'Erro ao excluir regra:\', err);\n  }\n}\n\n// ========================================================\n// CONTROLE DE MODAIS E FORMULÁRIOS\n// ========================================================\nfunction openModal(modalId) {\n  const modal = document.getElementById(modalId);\n  if (modal) modal.classList.remove(\'hidden\');\n}\n\nfunction closeModal(modalId) {\n  const modal = document.getElementById(modalId);\n  if (modal) modal.classList.add(\'hidden\');\n}\n\nfunction closeAllModals() {\n  document.querySelectorAll(\'.modal-backdrop\').forEach(modal => {\n    modal.classList.add(\'hidden\');\n  });\n}\n\nfunction setTipoLancamento(tipo) {\n  state.currentTipoLancamento = tipo;\n\n  const btnDespesa = document.querySelector(\'.btn-tipo-transacao[data-tipo="despesa"]\');\n  const btnReceita = document.querySelector(\'.btn-tipo-transacao[data-tipo="receita"]\');\n  const btnTransf = document.querySelector(\'.btn-tipo-transacao[data-tipo="transferencia"]\');\n\n  [btnDespesa, btnReceita, btnTransf].forEach(btn => {\n    if (btn) {\n      btn.className = \'btn-tipo-transacao py-2 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1.5 text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white\';\n    }\n  });\n\n  const containerDestino = document.getElementById(\'container-conta-destino\');\n  const containerCategoria = document.getElementById(\'container-categoria\');\n  const containerStatus = document.getElementById(\'container-campo-status\');\n  const lblContaOrigem = document.getElementById(\'lbl-conta-origem\');\n\n  if (tipo === \'despesa\') {\n    btnDespesa.className = \'btn-tipo-transacao py-2 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1.5 bg-rose-600 text-white shadow-sm\';\n    containerDestino.classList.add(\'hidden\');\n    containerCategoria.classList.remove(\'hidden\');\n    containerStatus.classList.remove(\'hidden\');\n    lblContaOrigem.textContent = \'Conta Bancária *\';\n  } else if (tipo === \'receita\') {\n    btnReceita.className = \'btn-tipo-transacao py-2 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1.5 bg-emerald-600 text-white shadow-sm\';\n    containerDestino.classList.add(\'hidden\');\n    containerCategoria.classList.remove(\'hidden\');\n    containerStatus.classList.remove(\'hidden\');\n    lblContaOrigem.textContent = \'Conta de Depósito *\';\n  } else if (tipo === \'transferencia\') {\n    btnTransf.className = \'btn-tipo-transacao py-2 rounded-lg text-xs font-bold transition flex items-center justify-center gap-1.5 bg-indigo-600 text-white shadow-sm\';\n    containerDestino.classList.remove(\'hidden\');\n    containerCategoria.classList.add(\'hidden\');\n    containerStatus.classList.add(\'hidden\');\n    lblContaOrigem.textContent = \'Conta de Origem *\';\n  }\n\n  updateLancamentoCategorias();\n  lucide.createIcons();\n}\n\nfunction setTipoRecorrencia(tipo) {\n  state.currentRecTipo = tipo;\n  const btnDesp = document.querySelector(\'.btn-rec-tipo[data-tipo="despesa"]\');\n  const btnRec = document.querySelector(\'.btn-rec-tipo[data-tipo="receita"]\');\n\n  if (tipo === \'despesa\') {\n    btnDesp.className = \'btn-rec-tipo py-1.5 rounded-lg text-xs font-bold transition bg-rose-600 text-white\';\n    btnRec.className = \'btn-rec-tipo py-1.5 rounded-lg text-xs font-bold transition text-slate-600 dark:text-slate-400\';\n  } else {\n    btnRec.className = \'btn-rec-tipo py-1.5 rounded-lg text-xs font-bold transition bg-emerald-600 text-white\';\n    btnDesp.className = \'btn-rec-tipo py-1.5 rounded-lg text-xs font-bold transition text-slate-600 dark:text-slate-400\';\n  }\n\n  populateCategoriasSelects();\n}\n\n// ========================================================\n// CONFIGURAÇÃO DOS EVENT LISTENERS GERAIS\n// ========================================================\nfunction setupEventListeners() {\n  document.getElementById(\'btn-logout\')?.addEventListener(\'click\', handleLogout);\n  document.getElementById(\'btn-zerar-mes\')?.addEventListener(\'click\', zerarLancamentosMesAtual);\n\n  document.getElementById(\'btn-mes-anterior\')?.addEventListener(\'click\', () => changeMonth(-1));\n  document.getElementById(\'btn-mes-proximo\')?.addEventListener(\'click\', () => changeMonth(1));\n  document.getElementById(\'btn-mes-atual\')?.addEventListener(\'click\', resetToCurrentMonth);\n  document.getElementById(\'btn-toggle-theme\')?.addEventListener(\'click\', toggleTheme);\n\n  // Tabs\n  document.querySelectorAll(\'.nav-tab\').forEach(tab => {\n    tab.addEventListener(\'click\', () => {\n      document.querySelectorAll(\'.nav-tab\').forEach(t => {\n        t.className = \'nav-tab flex items-center gap-2 px-3 sm:px-4 py-2.5 text-xs sm:text-sm font-medium border-b-2 border-transparent text-slate-500 hover:text-slate-700 dark:text-slate-400 dark:hover:text-slate-200 whitespace-nowrap\';\n      });\n      tab.className = \'nav-tab active-tab flex items-center gap-2 px-3 sm:px-4 py-2.5 text-xs sm:text-sm font-medium border-b-2 border-indigo-600 text-indigo-600 dark:text-indigo-400 whitespace-nowrap\';\n\n      const tabTarget = tab.getAttribute(\'data-tab\');\n      state.activeTab = tabTarget;\n\n      document.querySelectorAll(\'.tab-pane\').forEach(p => p.classList.add(\'hidden\'));\n      const activePane = document.getElementById(`tab-${tabTarget}`);\n      if (activePane) activePane.classList.remove(\'hidden\');\n\n      loadAllData();\n    });\n  });\n\n  // Botões de Modal\n  document.getElementById(\'btn-open-modal-lancamento\')?.addEventListener(\'click\', () => {\n    if (state.contas.length === 0) {\n      Swal.fire({\n        icon: \'info\',\n        title: \'Cadastre uma Conta Primeiro\',\n        text: \'Para fazer um lançamento, você precisa cadastrar pelo menos uma conta bancária ou carteira.\',\n        confirmButtonText: \'Cadastrar Conta\',\n        confirmButtonColor: \'#4f46e5\'\n      }).then(() => {\n        document.getElementById(\'btn-quick-new-account\')?.click();\n      });\n      return;\n    }\n\n    document.getElementById(\'form-lancamento\').reset();\n    document.getElementById(\'modal-lancamento-titulo\').textContent = \'Novo Lançamento\';\n    document.getElementById(\'lancamento-id\').value = \'\';\n    document.getElementById(\'lancamento-data\').value = new Date().toISOString().split(\'T\')[0];\n    setTipoLancamento(\'despesa\');\n    openModal(\'modal-lancamento\');\n  });\n\n  document.getElementById(\'btn-quick-transfer\')?.addEventListener(\'click\', () => {\n    if (state.contas.length < 2) {\n      Swal.fire({\n        icon: \'info\',\n        title: \'Necessário 2 Contas\',\n        text: \'Você precisa ter pelo menos 2 contas cadastradas para realizar transferências entre elas.\',\n        confirmButtonColor: \'#4f46e5\'\n      });\n      return;\n    }\n    document.getElementById(\'form-transferencia-modal\').reset();\n    document.getElementById(\'transf-data\').value = new Date().toISOString().split(\'T\')[0];\n    openModal(\'modal-transferencia\');\n  });\n\n  document.getElementById(\'btn-quick-new-account\')?.addEventListener(\'click\', () => {\n    document.getElementById(\'form-conta\').reset();\n    document.getElementById(\'modal-conta-titulo\').textContent = \'Nova Conta Bancária\';\n    document.getElementById(\'conta-id\').value = \'\';\n    document.getElementById(\'conta-cor\').value = \'#3b82f6\';\n    document.getElementById(\'conta-cor-label\').textContent = \'#3b82f6\';\n    openModal(\'modal-conta\');\n  });\n\n  document.getElementById(\'btn-onboarding-conta\')?.addEventListener(\'click\', () => {\n    document.getElementById(\'btn-quick-new-account\')?.click();\n  });\n\n  document.getElementById(\'btn-nova-conta-tab\')?.addEventListener(\'click\', () => {\n    document.getElementById(\'btn-quick-new-account\')?.click();\n  });\n\n  document.getElementById(\'btn-modal-recorrencia\')?.addEventListener(\'click\', () => {\n    document.getElementById(\'form-recorrencia\').reset();\n    document.getElementById(\'modal-rec-titulo\').textContent = \'Nova Despesa / Receita Recorrente\';\n    document.getElementById(\'rec-id\').value = \'\';\n    document.getElementById(\'rec-dia\').value = \'5\';\n    document.getElementById(\'rec-data-inicio\').value = new Date().toISOString().split(\'T\')[0];\n    document.getElementById(\'rec-data-fim\').value = \'\';\n    setTipoRecorrencia(\'despesa\');\n    openModal(\'modal-recorrencia\');\n  });\n\n  document.getElementById(\'btn-nova-categoria-tab\')?.addEventListener(\'click\', () => {\n    document.getElementById(\'form-categoria\').reset();\n    openModal(\'modal-categoria\');\n  });\n\n  document.getElementById(\'btn-force-generate-recurring\')?.addEventListener(\'click\', forceGenerateRecurring);\n\n  document.querySelectorAll(\'.btn-tipo-transacao\').forEach(btn => {\n    btn.addEventListener(\'click\', () => setTipoLancamento(btn.getAttribute(\'data-tipo\')));\n  });\n\n  document.querySelectorAll(\'.btn-rec-tipo\').forEach(btn => {\n    btn.addEventListener(\'click\', () => setTipoRecorrencia(btn.getAttribute(\'data-tipo\')));\n  });\n\n  document.getElementById(\'conta-cor\')?.addEventListener(\'input\', (e) => {\n    document.getElementById(\'conta-cor-label\').textContent = e.target.value;\n  });\n\n  document.querySelectorAll(\'.btn-close-modal\').forEach(btn => {\n    btn.addEventListener(\'click\', closeAllModals);\n  });\n\n  window.addEventListener(\'click\', (e) => {\n    if (e.target.classList.contains(\'modal-backdrop\')) closeAllModals();\n  });\n\n  // Filtros\n  [\'filtro-busca\', \'filtro-conta\', \'filtro-categoria\', \'filtro-tipo\', \'filtro-status\'].forEach(id => {\n    const el = document.getElementById(id);\n    if (el) {\n      el.addEventListener(\'input\', () => loadTransacoes());\n      el.addEventListener(\'change\', () => loadTransacoes());\n    }\n  });\n\n  document.getElementById(\'btn-limpar-filtros\')?.addEventListener(\'click\', () => {\n    document.getElementById(\'filtro-busca\').value = \'\';\n    document.getElementById(\'filtro-conta\').value = \'\';\n    document.getElementById(\'filtro-categoria\').value = \'\';\n    document.getElementById(\'filtro-tipo\').value = \'\';\n    document.getElementById(\'filtro-status\').value = \'\';\n    loadTransacoes();\n  });\n\n  // Form Lançamento\n  document.getElementById(\'form-lancamento\')?.addEventListener(\'submit\', async (e) => {\n    e.preventDefault();\n    const id = document.getElementById(\'lancamento-id\').value;\n    const tipo = state.currentTipoLancamento;\n    const descricao = document.getElementById(\'lancamento-descricao\').value;\n    const valor = parseFloat(document.getElementById(\'lancamento-valor\').value);\n    const data = document.getElementById(\'lancamento-data\').value;\n    const status = tipo === \'transferencia\' ? \'pago\' : document.getElementById(\'lancamento-status\').value;\n    const contaId = document.getElementById(\'lancamento-conta\').value;\n    const contaDestinoId = tipo === \'transferencia\' ? document.getElementById(\'lancamento-conta-destino\').value : null;\n    const categoriaId = tipo !== \'transferencia\' ? document.getElementById(\'lancamento-categoria\').value || null : null;\n    const observacoes = document.getElementById(\'lancamento-observacoes\').value;\n\n    const payload = { tipo, descricao, valor, data, status, conta_id: contaId, conta_destino_id: contaDestinoId, categoria_id: categoriaId, observacoes };\n    const url = id ? `/api/transacoes/${id}` : \'/api/transacoes\';\n    const method = id ? \'PUT\' : \'POST\';\n\n    try {\n      const res = await fetch(url, {\n        method,\n        headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify(payload)\n      });\n      const resData = await res.json();\n      if (resData.success) {\n        closeModal(\'modal-lancamento\');\n        await loadAllData();\n        Swal.fire({ icon: \'success\', title: id ? \'Lançamento Atualizado!\' : \'Lançamento Salvo!\', timer: 1400, showConfirmButton: false });\n      } else {\n        Swal.fire({ icon: \'error\', title: \'Erro\', text: resData.error });\n      }\n    } catch (err) {\n      console.error(err);\n    }\n  });\n\n  // Form Transferência\n  document.getElementById(\'form-transferencia-modal\')?.addEventListener(\'submit\', async (e) => {\n    e.preventDefault();\n    const contaOrigem = document.getElementById(\'transf-origem\').value;\n    const contaDestino = document.getElementById(\'transf-destino\').value;\n    const valor = parseFloat(document.getElementById(\'transf-valor\').value);\n    const data = document.getElementById(\'transf-data\').value;\n    const descricao = document.getElementById(\'transf-descricao\').value;\n\n    try {\n      const res = await fetch(\'/api/transferencias\', {\n        method: \'POST\',\n        headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify({ conta_origem_id: contaOrigem, conta_destino_id: contaDestino, valor, data, descricao })\n      });\n      const resData = await res.json();\n      if (resData.success) {\n        closeModal(\'modal-transferencia\');\n        await loadAllData();\n        Swal.fire({ icon: \'success\', title: \'Transferência Realizada!\', timer: 1400, showConfirmButton: false });\n      } else {\n        Swal.fire({ icon: \'error\', title: \'Erro\', text: resData.error });\n      }\n    } catch (err) {\n      console.error(err);\n    }\n  });\n\n  // Form Conta\n  document.getElementById(\'form-conta\')?.addEventListener(\'submit\', async (e) => {\n    e.preventDefault();\n    const id = document.getElementById(\'conta-id\').value;\n    const nome = document.getElementById(\'conta-nome\').value;\n    const instituicao = document.getElementById(\'conta-instituicao\').value;\n    const tipo = document.getElementById(\'conta-tipo\').value;\n    const saldoInicial = parseFloat(document.getElementById(\'conta-saldo-inicial\').value) || 0;\n    const cor = document.getElementById(\'conta-cor\').value;\n\n    const payload = { nome, instituicao, tipo, saldo_inicial: saldoInicial, cor };\n    const url = id ? `/api/contas/${id}` : \'/api/contas\';\n    const method = id ? \'PUT\' : \'POST\';\n\n    try {\n      const res = await fetch(url, {\n        method,\n        headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify(payload)\n      });\n      const resData = await res.json();\n      if (resData.success) {\n        closeModal(\'modal-conta\');\n        await loadAllData();\n        Swal.fire({ icon: \'success\', title: id ? \'Conta Atualizada!\' : \'Conta Criada!\', timer: 1400, showConfirmButton: false });\n      } else {\n        Swal.fire({ icon: \'error\', title: \'Erro\', text: resData.error });\n      }\n    } catch (err) {\n      console.error(err);\n    }\n  });\n\n  // Form Recorrência\n  document.getElementById(\'form-recorrencia\')?.addEventListener(\'submit\', async (e) => {\n    e.preventDefault();\n    const id = document.getElementById(\'rec-id\').value;\n    const tipo = state.currentRecTipo;\n    const descricao = document.getElementById(\'rec-descricao\').value;\n    const valor = parseFloat(document.getElementById(\'rec-valor\').value);\n    const diaVencimento = parseInt(document.getElementById(\'rec-dia\').value);\n    const dataInicio = document.getElementById(\'rec-data-inicio\').value;\n    const dataFim = document.getElementById(\'rec-data-fim\').value || null;\n    const contaId = document.getElementById(\'rec-conta\').value || null;\n    const categoriaId = document.getElementById(\'rec-categoria\').value || null;\n\n    const payload = { tipo, descricao, valor, dia_vencimento: diaVencimento, data_inicio: dataInicio, data_fim: dataFim, frequencia: \'mensal\', conta_id: contaId, categoria_id: categoriaId };\n    const url = id ? `/api/recorrencias/${id}` : \'/api/recorrencias\';\n    const method = id ? \'PUT\' : \'POST\';\n\n    try {\n      const res = await fetch(url, {\n        method,\n        headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify(payload)\n      });\n      const resData = await res.json();\n      if (resData.success) {\n        closeModal(\'modal-recorrencia\');\n        await loadAllData();\n        Swal.fire({ icon: \'success\', title: id ? \'Recorrência Atualizada!\' : \'Recorrência Cadastrada!\', timer: 1400, showConfirmButton: false });\n      } else {\n        Swal.fire({ icon: \'error\', title: \'Erro\', text: resData.error });\n      }\n    } catch (err) {\n      console.error(err);\n    }\n  });\n\n  // Form Categoria\n  document.getElementById(\'form-categoria\')?.addEventListener(\'submit\', async (e) => {\n    e.preventDefault();\n    const nome = document.getElementById(\'cat-nome\').value;\n    const tipo = document.getElementById(\'cat-tipo\').value;\n    const cor = document.getElementById(\'cat-cor\').value;\n\n    try {\n      const res = await fetch(\'/api/categorias\', {\n        method: \'POST\',\n        headers: { \'Content-Type\': \'application/json\' },\n        body: JSON.stringify({ nome, tipo, cor })\n      });\n      const resData = await res.json();\n      if (resData.success) {\n        closeModal(\'modal-categoria\');\n        await fetchCategorias();\n        renderCategoriasTab();\n        Swal.fire({ icon: \'success\', title: \'Categoria Criada!\', timer: 1400, showConfirmButton: false });\n      } else {\n        Swal.fire({ icon: \'error\', title: \'Erro\', text: resData.error });\n      }\n    } catch (err) {\n      console.error(err);\n    }\n  });\n\n  // Atalhos de Teclado\n  window.addEventListener(\'keydown\', (e) => {\n    const isInput = [\'INPUT\', \'TEXTAREA\', \'SELECT\'].includes(document.activeElement.tagName);\n    if (!isInput && !e.ctrlKey && !e.metaKey) {\n      if (e.key === \'n\' || e.key === \'N\') {\n        e.preventDefault();\n        document.getElementById(\'btn-open-modal-lancamento\')?.click();\n      } else if (e.key === \'i\' || e.key === \'I\') {\n        e.preventDefault();\n        document.getElementById(\'btn-open-modal-import\')?.click();\n      }\n    } else if (e.key === \'Escape\') {\n      closeAllModals();\n    }\n  });\n}\n'
